var THEME_ALIASES = {
    amber: "fallout"
};
var THEME_ORDER = ["cyber", "icecream", "fallout", "submarine", "matrix", "volcano"];
var DEFAULT_THEME_NAME = "submarine";
var UI = { ...THEMES[DEFAULT_THEME_NAME] };
var currentThemeName = DEFAULT_THEME_NAME;

var Theme = {
    listeners: [],

    getTheme(name) {
        const normalizedName = THEME_ALIASES[name] || name;
        return THEMES[normalizedName] || THEMES[DEFAULT_THEME_NAME];
    },

    set(name, persist = false) {
        const normalizedName = THEME_ALIASES[name] || name;
        currentThemeName = THEMES[normalizedName] ? normalizedName : DEFAULT_THEME_NAME;
        UI = { ...this.getTheme(currentThemeName) };
        this.applyToPage();
        this.notify();

        if (persist && typeof updateStoredSubsonicConfig === "function") {
            updateStoredSubsonicConfig({ theme: currentThemeName });
        }
    },

    toggle() {
        const currentIndex = THEME_ORDER.indexOf(currentThemeName);
        const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % THEME_ORDER.length : 0;
        this.set(THEME_ORDER[nextIndex], true);
    },

    onChange(callback) {
        if (typeof callback === "function") {
            this.listeners.push(callback);
        }
    },

    notify() {
        for (const listener of this.listeners) {
            listener(UI, currentThemeName);
        }
    },

    applyToPage() {
        const root = document.documentElement;
        if (!root) {
            return;
        }

        root.style.setProperty("--bg", rgbString(UI.bg));
        root.style.setProperty("--panel", rgbaString(UI.panel, 0.92));
        root.style.setProperty("--panel-soft", rgbaString(UI.panelAlt, 0.88));
        root.style.setProperty("--line", rgbaString(UI.line, 0.36));
        root.style.setProperty("--cyan", cssHex(UI.line));
        root.style.setProperty("--pink", cssHex(UI.pink));
        root.style.setProperty("--amber", cssHex(UI.amber));
        root.style.setProperty("--text", cssHex(UI.text));
        root.style.setProperty("--muted", cssHex(UI.muted));
        root.style.setProperty("--field", cssHex(UI.field));
        const darkTheme = currentThemeName === "cyber" || currentThemeName === "fallout" || currentThemeName === "submarine" || currentThemeName === "matrix" || currentThemeName === "volcano";
        root.style.setProperty("--line-soft", rgbaString(UI.line, darkTheme ? 0.16 : 0.24));
        root.style.setProperty("--pink-soft", rgbaString(UI.pink, darkTheme ? 0.11 : 0.18));
        root.style.setProperty("--shell-shadow", UI.shadow);
        if (document.body) {
            document.body.dataset.theme = currentThemeName;
        }
    }
};

Theme.applyToPage();

function setTheme(name, persist = false) {
    Theme.set(name, persist);
}

function toggleTheme() {
    Theme.toggle();
}

function rgbString(value) {
    return `rgb(${value[0]}, ${value[1]}, ${value[2]})`;
}

function rgbaString(value, alpha) {
    return `rgba(${value[0]}, ${value[1]}, ${value[2]}, ${alpha})`;
}

function cssHex(value) {
    return "#" + value.map((part) => Math.max(0, Math.min(255, part)).toString(16).padStart(2, "0")).join("");
}

/* ---- lib/subsonic.js ---- */
class SubsonicClient {
    /**
     * Creates an instance of SubsonicClient.
     * @param {string} server - The server URL.
     * @param {string} user - The username.
     * @param {string} token - The authentication token.
     * @param {string} salt - The salt for the token.
     * @param {string} [version="1.16.0"] - The API version.
     * @param {string} [client="SubsonicNeonDeck"] - The client name.
     */
    constructor(server, user, token, salt, version = "1.16.0", client = "SubsonicNeonDeck") {
        this.server = server;
        this.user = user;
        this.token = token;
        this.salt = salt;
        this.version = version;
        this.client = client;
    }

    asArray(value) {
        if (!value) {
            return [];
        }

        return Array.isArray(value) ? value : [value];
    }

    /**
     * Builds authenticated Subsonic URLs with URLSearchParams so ids,
     * usernames, and tokens are encoded consistently across endpoints.
     */
    buildAuthenticatedUrl(endpoint, params = {}, options = {}) {
        const url = new URL(`${this.server}/rest/${endpoint}`);
        const query = {
            ...params,
            u: this.user,
            t: this.token,
            s: this.salt,
            v: this.version,
            c: this.client
        };

        if (options.formatJson) {
            query.f = "json";
        }

        Object.keys(query).forEach((key) => {
            const value = query[key];
            if (value !== undefined && value !== null) {
                url.searchParams.append(key, value);
            }
        });

        return url;
    }

    /**
     * Makes a request to the Subsonic API.
     * @param {string} endpoint - The API endpoint.
     * @param {Object} [params={}] - The query parameters.
     * @returns {Promise<Object|null>} The response data or null if the request failed.
     */
    async request(endpoint, params = {}) {
        try {
            const url = this.buildAuthenticatedUrl(endpoint, params, { formatJson: true });
            const response = await fetch(url);
            if (!response.ok) {
                throw new Error(`HTTP ${response.status} ${response.statusText}`);
            }

            const data = await response.json();
            const subsonicResponse = data?.['subsonic-response'];

            if (!subsonicResponse) {
                throw new Error("Subsonic API Error: missing subsonic-response");
            }

            if (subsonicResponse.status === "ok") {
                return subsonicResponse;
            } else {
                throw new Error("Subsonic API Error: " + JSON.stringify(subsonicResponse));
            }
        } catch (error) {
            console.error("Request failed:", error);
            return null;
        }
    }

    /**
     * Retrieves a list of artists.
     * @returns {Promise<Array>} The list of artists.
     */
    async getArtists() {
        const data = await this.request("getArtists");
        return this.asArray(data?.artists?.index);
    }

    /**
     * Retrieves information about a specific artist.
     * Includes a link to the artist's albums. <---HERE
     * @param {string} artistId - The artist ID.
     * @returns {Promise<Object|null>} The artist information or null if not found.
     */
    async getArtist(artistId) {
        const data = await this.request("getArtist", { id: artistId });
        return data?.artist || null;
    }

    /**
     * Retrieves information about a specific album.
     * @param {string} albumId - The album ID.
     * @returns {Promise<Object|null>} The album information or null if not found.
     */
    async getAlbum(albumId) {
        const data = await this.request("getAlbum", { id: albumId });
        if (data?.album?.song) {
            data.album.song = this.asArray(data.album.song).map(song => ({
                ...song,
                link: this.getSong(song.id)
            }));
        }
        return data?.album || null;
    }

    /**
     * Retrieves the URL to stream a specific song.
     * @param {string} songId - The song ID.
     * @returns {string} The URL to stream the song.
     */
    getSong(songId) {
        return this.buildAuthenticatedUrl("stream", { id: songId }).toString();
    }

    /**
     * Retrieves information about a specific song.
     * @param {string} songId - The song ID.
     * @returns {Promise<Object|null>} The song information or null if not found.
     */
    async getSongInfo(songId) {
        const data = await this.request("getSong", { id: songId });
        return data?.song || null;
    }

    /**
     * Searches for songs matching the query.
     * @param {string} query - The search query.
     * @returns {Promise<Object>} The search results including albums, artists, and songs with links.
     */
    async search(query) {
        const data = await this.request("search3", { query });
        const albums = this.asArray(data?.searchResult3?.album);
        const songs = this.asArray(data?.searchResult3?.song);
        const artists = this.asArray(data?.searchResult3?.artist);

        // Use getAlbum to obtain the details for every album
        const albumsWithSongs = await Promise.all(albums.map(async album => {
            const albumDetails = await this.getAlbum(album.id);
            return albumDetails ? { ...album, song: albumDetails.song } : album;
        }));

        return {
            album: albumsWithSongs,
            artist: artists,
            song: songs.map(song => ({
                ...song,
                link: this.getSong(song.id)
            }))
        };
    }

    /**
     * Displays search results in a specified container.
     * @param {string} query - The search query.
     * @param {string} containerId - The ID of the container to display results in.
     */
    async displaySearchResults(query, containerId) {
        const results = await this.search(query);
        const container = document.getElementById(containerId);
        container.replaceChildren();

        if (results.song.length > 0) {
            results.song.forEach(song => {
                const songElement = document.createElement("div");
                songElement.textContent = `${song.artist} - ${song.title}`;
                container.appendChild(songElement);
            });
        } else {
            container.textContent = "No results found.";
        }
    }

    /**
     * Logs search results to the console.
     * @param {string} query - The search query.
     */
    async consoleSearch(query) {
        const results = await this.search(query);
        if (results.song.length > 0) {
            results.song.forEach(song => {
                console.log(`${song.id} - ${song.artist} - ${song.title}`);
            });
        } else {
            console.log("No results found.");
        }
    }

    /**
     * Returns a list of music folders
     */
    async getMusicFolders() {
        const data = await this.request("getMusicFolders");
        return this.asArray(data?.musicFolders?.musicFolder);
    }

    /**
     * Returns the music directory
     */
    async getMusicDirectory(Id) {
        const data = await this.request("getMusicDirectory",{ id:Id });
        return this.asArray(data?.directory?.child);
    }


    /*
    * Returns the full index. (this is represents the folder structure of the music library)
    * @param {int} - The index id to retrieve (0 for the first index)
    */
    async getIndexes(id=0) {
        const data = await this.request("getIndexes",{ musicFolderId:id });
        return {
            index: this.asArray(data?.indexes?.index),
            child: this.asArray(data?.indexes?.child)
        };
    }



    /**
     * Returns the playlists
     */
    async getPlaylists() {
        const data = await this.request("getPlaylists");
        return this.asArray(data?.playlists?.playlist);

    }

    /**
     * Returns the playlist
     */
    async getPlaylist(Id) {
        const data = await this.request("getPlaylist",{ id:Id });
        return {
            ...data?.playlist,
            entry: this.asArray(data?.playlist?.entry)
        };

    }

    // TODO: Lyrics feature is parked until the external lyrics API is available again.
    // /**
    //  * Returns the current song lyrics
    //  * @param {string} title - The song title
    //  * @param {string} artist - The artist name
    //  * @returns {Promise<string|null>} The lyrics of the song or null if not found
    //  */
    // async getLyrics(artist,title) {
    //     const data = await this.request("getLyrics", { title, artist });
    //     return data?.lyrics?.value || null;
    //
    // }


    /**
     * Runs a command on the Subsonic server.
     * @param {string} command - The command to run.
     * @returns {Promise<Object|null>} The response from the server or null if the command failed.
     */
    async runCommand(command) {
        const data = await this.request(command);
        return data || null;
    }

    /**
     * Gets the cover art URL for a given ID.
     * Rough on the edges but meh, it works.
     * @param {*} id
     * @returns
     */
    getCoverArt(id) {
        return this.buildAuthenticatedUrl("getCoverArt", { id: id, size: 100 }).toString();
    }

}

/* ---- lib/textlistbox.js ---- */
/**
 * Reusable p5 text list box with fixed-height rows, truncation, and optional
 * scrollbar. It is intentionally small so playlist, logs, and command-style
 * panels can share the same visual primitive later.
 */
class TextListBox {
    /**
     * Creates a reusable canvas list box.
     * @param {number} x - Left coordinate in canvas space.
     * @param {number} y - Top coordinate in canvas space.
     * @param {number} w - Box width.
     * @param {number} h - Box height.
     * @param {Object} options - Row sizing, font, scrollbar, and autoscroll options.
     */
    constructor(x, y, w, h, options = {}) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.items = [];
        this.itemHeight = options.itemHeight || 18;
        this.fontSize = options.fontSize || 11;
        this.scrollbarWidth = options.scrollbarWidth || 16;
        this.paddingX = options.paddingX || 6;
        this.selectedIndex = options.selectedIndex ?? -1;
        this.autoStickToBottom = options.autoStickToBottom === true;
        this.scrollOffset = 0;
        this.scrollbarDragging = false;
        this.scrollbarY = 0;
        this.scrollbarHeight = 0;
        this.scrollbarDragOffset = 0;
        this.lastItemCount = 0;
        // True after the user scrolls away from the bottom. New items should
        // not force the view downward while the user is reading older lines.
        this.userPinned = false;
    }

    /**
     * Updates the list rectangle and keeps the current scroll offset valid.
     */
    setBounds(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.clampScrollOffset();
    }

    /**
     * Replaces the visible item model. If bottom-stick is enabled and the user
     * has not pinned history, new rows keep the list scrolled to the bottom.
     */
    setItems(items) {
        const wasAtBottom = this.isAtBottom();
        this.items = Array.isArray(items) ? items : [];
        // A log-like list should follow new rows only while the user is already
        // at the bottom. Once they scroll upward, userPinned preserves history.
        if (this.autoStickToBottom && !this.userPinned && (this.items.length !== this.lastItemCount || wasAtBottom)) {
            this.scrollToBottom();
        } else {
            this.clampScrollOffset();
        }
        // Reaching the bottom re-arms autoscroll for future appended rows.
        if (this.isAtBottom()) {
            this.userPinned = false;
        }
        this.lastItemCount = this.items.length;
    }

    /**
     * Returns the number of whole rows that can be drawn in the box.
     */
    getVisibleCount() {
        return Math.max(1, Math.floor(this.h / this.itemHeight));
    }

    /**
     * Returns the largest valid first-row index for the current item count.
     */
    getMaxScrollOffset() {
        return Math.max(0, this.items.length - this.getVisibleCount());
    }

    /**
     * Keeps scrollOffset inside the legal range after resize or data changes.
     */
    clampScrollOffset() {
        this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, this.getMaxScrollOffset()));
    }

    /**
     * Moves the viewport to the newest rows.
     */
    scrollToBottom() {
        this.scrollOffset = this.getMaxScrollOffset();
    }

    /**
     * Reports whether the newest row is currently visible.
     */
    isAtBottom() {
        return this.scrollOffset >= this.getMaxScrollOffset();
    }

    /**
     * Draws the box background, visible rows, selection highlight, and scrollbar.
     */
    draw() {
        push();
        noStroke();
        fill(UI.surface[0], UI.surface[1], UI.surface[2], 238);
        rect(this.x, this.y, this.w, this.h, 4);

        this.clampScrollOffset();
        const visibleCount = this.getVisibleCount();
        const maxTextWidth = Math.max(20, this.w - this.scrollbarWidth - this.paddingX * 2);

        textSize(this.fontSize);
        textAlign(LEFT, TOP);

        // Draw only rows inside the viewport. This keeps rendering bounded even
        // if the backing log/list contains many more entries.
        for (let i = 0; i < visibleCount; i++) {
            const itemIndex = i + this.scrollOffset;
            if (itemIndex >= this.items.length) {
                break;
            }

            const item = this.normalizeItem(this.items[itemIndex]);
            const rowY = this.y + i * this.itemHeight;
            if (itemIndex === this.selectedIndex) {
                fill(UI.line[0], UI.line[1], UI.line[2], 36);
                rect(this.x, rowY, this.w - this.scrollbarWidth, this.itemHeight);
            }

            fill(item.color || UI.text);
            text(this.truncateText(item.text, maxTextWidth), this.x + this.paddingX, rowY + 4);
        }

        this.drawScrollbar(visibleCount);
        pop();
    }

    /**
     * Converts string items and object items into one drawing shape.
     */
    normalizeItem(item) {
        if (typeof item === "string") {
            return { text: item, color: UI.text };
        }

        return {
            text: String(item?.text || ""),
            color: item?.color || UI.text
        };
    }

    /**
     * Truncates text to fit the row width and appends an ellipsis when needed.
     */
    truncateText(value, maxWidth) {
        let textToDisplay = String(value || "");
        let trimmed = false;

        while (textWidth(textToDisplay) > maxWidth && textToDisplay.length > 0) {
            textToDisplay = textToDisplay.slice(0, -1);
            trimmed = true;
        }

        return trimmed ? textToDisplay.trim() + "..." : textToDisplay;
    }

    /**
     * Draws a playlist/filebrowser-style scrollbar for the current viewport.
     */
    drawScrollbar(visibleCount) {
        if (this.items.length <= visibleCount) {
            stroke(UI.line[0], UI.line[1], UI.line[2], 70);
            line(this.x + this.w - this.scrollbarWidth, this.y, this.x + this.w - this.scrollbarWidth, this.y + this.h);
            noStroke();
            return;
        }

        // Scrollbar position is derived from the current first visible row.
        this.scrollbarHeight = Math.max((visibleCount / this.items.length) * this.h, 20);
        this.scrollbarY = this.y + (this.scrollOffset / this.getMaxScrollOffset()) * (this.h - this.scrollbarHeight);
        this.scrollbarY = Math.max(this.y, Math.min(this.scrollbarY, this.y + this.h - this.scrollbarHeight));

        fill(UI.line[0], UI.line[1], UI.line[2], 190);
        rect(this.x + this.w - this.scrollbarWidth + 5, this.scrollbarY, 7, this.scrollbarHeight, 4);

        stroke(UI.line[0], UI.line[1], UI.line[2], 70);
        line(this.x + this.w - this.scrollbarWidth, this.y, this.x + this.w - this.scrollbarWidth, this.y + this.h);
        noStroke();
    }

    /**
     * Tests whether a point is inside the list box.
     */
    contains(mx, my) {
        return mx >= this.x && mx <= this.x + this.w && my >= this.y && my <= this.y + this.h;
    }

    /**
     * Handles mouse-wheel scrolling. Scrolling away from the bottom pins the
     * viewport to history until the user returns to the newest rows.
     */
    handleWheel(delta) {
        this.scrollOffset += delta > 0 ? 1 : -1;
        this.clampScrollOffset();
        this.userPinned = !this.isAtBottom();
    }

    /**
     * Starts scrollbar dragging. Clicking anywhere in the scrollbar column
     * jumps the thumb there and begins a drag, which is easier on touch screens.
     */
    handleMousePressed(mx, my) {
        if (!this.contains(mx, my) || this.items.length <= this.getVisibleCount()) {
            return false;
        }

        if (mx >= this.x + this.w - this.scrollbarWidth && mx <= this.x + this.w) {
            this.scrollbarDragging = true;
            // If the user clicks outside the thumb but inside the track, center
            // the thumb on that click before converting it to a scroll offset.
            this.scrollbarDragOffset = my >= this.scrollbarY && my <= this.scrollbarY + this.scrollbarHeight
                ? my - this.scrollbarY
                : this.scrollbarHeight / 2;
            this.handleMouseDrag(mx, my);
            return true;
        }

        return false;
    }

    /**
     * Updates the scrollbar thumb and converts its position into a row offset.
     */
    handleMouseDrag(mx, my) {
        if (!this.scrollbarDragging) {
            return false;
        }

        const maxScrollY = this.y + this.h - this.scrollbarHeight;
        this.scrollbarY = Math.max(this.y, Math.min(my - this.scrollbarDragOffset, maxScrollY));
        this.scrollOffset = Math.round(((this.scrollbarY - this.y) / Math.max(1, this.h - this.scrollbarHeight)) * this.getMaxScrollOffset());
        this.clampScrollOffset();
        this.userPinned = !this.isAtBottom();
        return true;
    }

    /**
     * Ends an active scrollbar drag.
     */
    handleMouseRelease() {
        this.scrollbarDragging = false;
    }
}

/* ---- lib/telemetrylog.js ---- */
/**
 * Central event buffer for the deck. Producers emit source/message pairs; the
 * DATA FEED panel decides how to present the resulting entries.
 */
class TelemetryLog {
    /**
     * Creates a bounded in-memory event log.
     * @param {number} maxEntries - Maximum entries retained for rendering.
     */
    constructor(maxEntries = 160) {
        this.maxEntries = maxEntries;
        this.entries = [];
        // PERF PATCH [bounded-telemetry-key-history]: entries are bounded, but
        // throttle/dedupe keys also need a cap as track-specific keys change.
        this.maxTrackedKeys = Math.max(64, maxEntries * 2);
        // Tracks last accepted event per key so noisy metrics can be throttled
        // or deduplicated without making producers manage that state.
        this.lastByKey = new Map();
    }

    /**
     * Adds a telemetry event if it passes throttle and dedupe rules.
     * @param {string} source - Short source label, for example SYSTEM or AUDIO.
     * @param {string} message - Message body without timestamp or source label.
     * @param {Object} options - Optional key, throttleMs, dedupe, level, fullTimestamp.
     * @returns {boolean} True when the entry was accepted into the buffer.
     */
    emit(source, message, options = {}) {
        const now = Date.now();
        const normalizedSource = String(source || "SYSTEM").toUpperCase();
        const normalizedMessage = String(message || "");
        const key = options.key || `${normalizedSource}:${normalizedMessage}`;
        const previous = this.lastByKey.get(key);

        // Throttle by logical key, not by exact message, so changing metric
        // values still cannot flood the DATA FEED every animation frame.
        if (previous && options.throttleMs && now - previous.time < options.throttleMs) {
            return false;
        }

        // Dedupe suppresses repeated state messages such as unchanged FX values.
        if (previous && options.dedupe && previous.message === normalizedMessage) {
            return false;
        }

        const entry = {
            timestamp: new Date(now),
            source: normalizedSource,
            message: normalizedMessage,
            level: options.level || "info",
            // SYSTEM entries anchor the session timeline with full date/time.
            // Other sources stay compact and show only time in TelemetryPanel.
            fullTimestamp: options.fullTimestamp === true || normalizedSource === "SYSTEM"
        };

        this.entries.push(entry);
        // Trim from the front so the newest entries are always retained.
        if (this.entries.length > this.maxEntries) {
            this.entries.shift();
        }

        // Refresh insertion order for accepted keys, then trim key memory so
        // track-specific telemetry cannot grow forever during long sessions.
        if (this.lastByKey.has(key)) {
            this.lastByKey.delete(key);
        }
        this.lastByKey.set(key, {
            time: now,
            message: normalizedMessage
        });
        this.trimTrackedKeys();

        return true;
    }

    /**
     * Keeps throttle/dedupe metadata bounded independently from visible log
     * entries. Map preserves insertion order, so the oldest keys are removed.
     * This prevents long sessions with track-specific keys from growing the
     * telemetry metadata map forever.
     */
    trimTrackedKeys() {
        // PERF PATCH [bounded-telemetry-key-history]: discard oldest logical
        // keys while keeping recent throttling useful for noisy telemetry.
        while (this.lastByKey.size > this.maxTrackedKeys) {
            const oldestKey = this.lastByKey.keys().next().value;
            this.lastByKey.delete(oldestKey);
        }
    }

    /**
     * Returns a shallow copy so renderers cannot mutate the log buffer.
     */
    getEntries() {
        return this.entries.slice();
    }

    /**
     * Clears the event buffer and throttle/dedupe memory.
     */
    clear() {
        this.entries = [];
        this.lastByKey.clear();
    }
}

/* ---- lib/telemetrypanel.js ---- */
/**
 * Panel-bound renderer for the DATA FEED. It uses TextListBox so this log can
 * become the first reusable text-interface surface in the deck.
 */
class TelemetryPanel {
    /**
     * Creates the panel-bound DATA FEED renderer.
     * @param {TelemetryLog} telemetryLog - Shared app telemetry buffer.
     */
    constructor(telemetryLog) {
        this.telemetryLog = telemetryLog;
        this.x = 0;
        this.y = 0;
        this.w = 260;
        this.h = 120;
        this.inactive = false;
        this.textBox = new TextListBox(0, 0, 260, 120, {
            itemHeight: 18,
            fontSize: 11,
            autoStickToBottom: true
        });
    }

    /**
     * Renders current telemetry entries into the internal TextListBox.
     */
    draw() {
        if (this.inactive || !this.telemetryLog) {
            return;
        }

        // Convert entries to draw-ready rows here so TextListBox stays generic.
        const items = this.telemetryLog.getEntries().map((entry) => ({
            text: this.formatEntry(entry),
            color: this.getEntryColor(entry)
        }));
        this.textBox.setItems(items);
        this.textBox.draw();
    }

    /**
     * Formats one telemetry entry as the visible log line.
     */
    formatEntry(entry) {
        const stamp = entry.fullTimestamp
            ? this.formatDateTime(entry.timestamp)
            : this.formatTime(entry.timestamp);
        return `[${stamp}] [${entry.source}] ${entry.message}`;
    }

    /**
     * Formats a timestamp with date and time for SYSTEM-level events.
     */
    formatDateTime(date) {
        return `${date.getFullYear()}-${this.pad(date.getMonth() + 1)}-${this.pad(date.getDate())} ${this.formatTime(date)}`;
    }

    /**
     * Formats a compact time-only timestamp for high-frequency module events.
     */
    formatTime(date) {
        return `${this.pad(date.getHours())}:${this.pad(date.getMinutes())}:${this.pad(date.getSeconds())}`;
    }

    /**
     * Pads date/time numbers to two digits.
     */
    pad(value) {
        return String(value).padStart(2, "0");
    }

    /**
     * Maps event level/source into the current theme palette.
     */
    getEntryColor(entry) {
        if (entry.level === "error") {
            return UI.pink;
        }
        if (entry.level === "warn") {
            return UI.amber;
        }
        if (entry.source === "SYSTEM") {
            return UI.line;
        }
        return UI.text;
    }

    /**
     * Fits the text viewport inside the owning panel body.
     */
    fitToPanel(panel) {
        this.x = panel.x + 12;
        this.y = panel.y + 30;
        this.w = Math.max(120, panel.w - 24);
        this.h = Math.max(60, panel.h - 42);
        this.textBox.setBounds(this.x, this.y, this.w, this.h);
    }

    /**
     * Allows LayoutManager/Skinny-style filtering to hide this panel if needed.
     */
    setInactive(value) {
        this.inactive = !!value;
    }

    /**
     * Reports whether the panel is currently hidden/inactive.
     */
    isInactive() {
        return this.inactive;
    }

    /**
     * Minimum panel size used by LayoutManager resize handles.
     */
    getMinPanelSize() {
        return { w: 260, h: 110 };
    }

    /**
     * Delegates scrollbar press handling to the reusable text box.
     */
    handleMousePressed(mx, my) {
        return this.textBox.handleMousePressed(mx, my);
    }

    /**
     * Delegates scrollbar drag handling to the reusable text box.
     */
    handleMouseDrag(mx, my) {
        return this.textBox.handleMouseDrag(mx, my);
    }

    /**
     * Ends any active internal scrollbar drag.
     */
    handleMouseRelease() {
        this.textBox.handleMouseRelease();
    }

    /**
     * Scrolls DATA FEED history without allowing browser page scroll.
     */
    handleWheel(delta) {
        this.textBox.handleWheel(delta);
    }

    /**
     * Tests whether a pointer event belongs to the text viewport.
     */
    contains(mx, my) {
        return this.textBox.contains(mx, my);
    }
}

/* ---- lib/filebrowser.js ---- */
/**
 * Class that creates a file browser using the Subsonic API getIndexes() and getMusicDirectory()
 * and displays it in a scrollable list.
 * Allows navigation through folders and selection of songs to play.
 */
class FileBrowser {
    /**
     * Creates a new FileBrowser instance.
     * @param {number} x - The x-coordinate of the file browser.
     * @param {number} y - The y-coordinate of the file browser.
     * @param {number} w - The width of the file browser.
     * @param {number} h - The height of the file browser.
     * @param {Object} songsList - The playlist object to manage songs.
     * @param {Object} subsonicObj - The Subsonic API object to interact with the API.
     * @param {Object} playerObj - Playback controller used by normal click playback.
     * @param {TelemetryLog|null} telemetry - Optional DATA FEED logger.
     */
    constructor(x, y, w, h, songsList, subsonicObj, playerObj, telemetry = null) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.items = []; // items to display
        this.scrollOffset = 0; // scroll offset
        this.itemHeight = 20; // height of each item
        this.selectedIndex = 0; // selected item index
        this.fontSize = 12; // font size
        this.scrollbarWidth = 20; // width of scrollbar
        this.scrollbarColor = null; // Scrollbar drawing reads the active theme from UI.line.
        this.scrollbarDragging = false; // is scrollbar being dragged
        this.scrollbarDragOffset = 0; // offset when dragging scrollbar
        this.visibleItems = Math.floor(this.h / this.itemHeight); // number of visible items
        this.totalItems = 0; // total number of items
        this.scrollbarHeight = 0; // height of scrollbar
        this.scrollbarY = 0; // y position of scrollbar
        this.scrollbarHover = false; // is mouse over scrollbar
        this.subsonicObj = subsonicObj; // Subsonic API object
        this.loadIndexes(); // load indexes from Subsonic API
        this.songsList = songsList || []; // list of songs for playlist
        this.folderHistory = []; // stack to keep track of previous folder ids for navigation
        this.playerObj = playerObj; // Player object to play songs
        this.telemetry = telemetry; // DATA FEED logger for browser queue actions
        this.addMode = false; // When enabled, song clicks append to queue instead of replacing playback.
        // Browser row glyphs keep folder/song rows visually distinct without
        // changing the underlying Subsonic item model.
        this.folderIcon = "🗀";
        this.songIcon = "♪";

        // Toolbar properties
        this.toolbarWidth = 28; // Width of the vertical toolbar
        this.toolbarButtons = [
            {
                icon: "⟳", // Reload icon
                action: () => { this.loadIndexes(); this.folderHistory = []; }, // Action to invoke loadIndexes()
                color: color(246, 200, 95), // Button background color
                height: 20, // Button height
            },
            {
                icon: "←", // Back icon
                action: () => this.navigateBack(), // Action to invoke navigateBack()
                color: color(246, 200, 95), // Button background color
                height: 20, // Button height
            },
            {
                icon: "+", // Add mode toggle
                action: () => this.toggleAddMode(),
                active: () => this.addMode,
                height: 20,
            },
        ];
    }

    /**
     * Draws the file browser, including the toolbar, items, and scrollbar.
     */
    draw() {
        push();
        this.clampScrollOffset();
        // Draw the toolbar
        noStroke();
        fill(UI.panelAlt[0], UI.panelAlt[1], UI.panelAlt[2]);
        rect(this.x, this.y, this.toolbarWidth, this.h, 4);

        // Draw toolbar buttons
        let buttonY = this.y + 5; // Initial Y position for the first button
        for (const button of this.toolbarButtons) {
            const active = typeof button.active === "function" && button.active();
            const buttonColor = active ? UI.line : UI.amber;
            fill(buttonColor[0], buttonColor[1], buttonColor[2], active ? 80 : 45);
            stroke(buttonColor[0], buttonColor[1], buttonColor[2]);
            rect(this.x + 5, buttonY, this.toolbarWidth - 10, button.height, 3); // Use the button's height
            noStroke();
            fill(UI.text[0], UI.text[1], UI.text[2]);
            textSize(17);
            textAlign(CENTER, CENTER);
            text(button.icon, this.x + this.toolbarWidth / 2, buttonY + button.height / 2); // Center the icon
            buttonY += button.height + 5; // Add spacing between buttons
        }

        // Draw the file browser background
        noStroke();
        fill(UI.surface[0], UI.surface[1], UI.surface[2], 238);
        rect(this.x + this.toolbarWidth, this.y, this.w - this.toolbarWidth, this.h, 4);

        this.visibleItems = Math.floor(this.h / this.itemHeight); // recalculate visible items
        this.totalItems = this.items.length; // update total items

        // Set text properties
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(this.fontSize);
        textAlign(LEFT, TOP); // Align text to the left and top

        // Fill the box with items
        for (let i = 0; i < this.visibleItems; i++) {
            const itemIndex = i + this.scrollOffset;
            if (itemIndex >= this.totalItems) break;
            const item = this.items[itemIndex];

            // Highlight the selected item
            if (itemIndex === this.selectedIndex) {
                fill(UI.line[0], UI.line[1], UI.line[2], 36);
                rect(this.x + this.toolbarWidth, this.y + i * this.itemHeight, this.w - this.toolbarWidth - this.scrollbarWidth, this.itemHeight);
                fill(UI.text[0], UI.text[1], UI.text[2]);
            } else {
                fill(UI.muted[0], UI.muted[1], UI.muted[2]);
            }

            // Truncate text if it exceeds the width of the box
            let textToDisplay = this.getItemDisplayLabel(item);
            let trimmed = false;
            const maxTextWidth = this.w - this.toolbarWidth - this.scrollbarWidth - 15; // Account for padding and scrollbar
            while (textWidth(textToDisplay) > maxTextWidth) {
                textToDisplay = textToDisplay.slice(0, -1); // Remove the last character
                trimmed = true;
            }

            if (trimmed) textToDisplay = textToDisplay.trim() + "..."; // Add ellipsis

            // Draw the item name aligned to the left
            text(textToDisplay, this.x + this.toolbarWidth + 5, this.y + i * this.itemHeight + 5);
        }

        // Draw the scrollbar
        fill(UI.line[0], UI.line[1], UI.line[2]);

        if (this.totalItems > this.visibleItems) {
            // Calculate the scrollbar height based on the ratio of visible items to total items
            this.scrollbarHeight = Math.max((this.visibleItems / this.totalItems) * this.h, 20); // Ensure a minimum height

            // Calculate the scrollbar's Y position based on the current offset
            this.scrollbarY = this.y + (this.scrollOffset / (this.totalItems - this.visibleItems)) * (this.h - this.scrollbarHeight);

            // Clamp scrollbarY to ensure it stays within bounds
            if (this.scrollbarY < this.y) {
                this.scrollbarY = this.y;
            }
            if (this.scrollbarY + this.scrollbarHeight > this.y + this.h) {
                this.scrollbarY = this.y + this.h - this.scrollbarHeight;
            }

            // Draw scrollbar background
            rect(this.x + this.w - this.scrollbarWidth + 6, this.scrollbarY, 8, this.scrollbarHeight, 4);
            // Draw scrollbar border
            noStroke();
        }

        // Line to separate scrollbar
        stroke(UI.line[0], UI.line[1], UI.line[2], 70);
        line(this.x + this.w - this.scrollbarWidth, this.y, this.x + this.w - this.scrollbarWidth, this.y + this.h);
        noStroke();
        pop();
    }

    /**
     * Handles mouse pressed events.
     * Detects clicks on toolbar buttons, scrollbar, and items in the file browser.
     * @param {number} mx - The x-coordinate of the mouse click.
     * @param {number} my - The y-coordinate of the mouse click.
     * @param {Object} options - Optional behavior flags.
     * @param {boolean} options.addToQueue - Appends song clicks to the queue.
     * @returns {boolean} True when the browser consumed the click.
     */
    handleMouse(mx, my, options = {}) {
        // Check if the mouse is over a toolbar button
        let buttonY = this.y + 5; // Initial Y position for the first button
        for (const button of this.toolbarButtons) {
            if (
                mx > this.x + 5 &&
                mx < this.x + this.toolbarWidth - 5 &&
                my > buttonY &&
                my < buttonY + button.height
            ) {
                button.action(); // Invoke the button's action
                return true;
            }
            buttonY += button.height + 5; // Add spacing between buttons
        }

        // Check if mouse is over scrollbar
        if (
            mx > this.x + this.w - this.scrollbarWidth &&
            mx < this.x + this.w &&
            my > this.scrollbarY &&
            my < this.scrollbarY + this.scrollbarHeight
        ) {
            this.scrollbarHover = true;
            this.scrollbarDragging = true;
            this.scrollbarDragOffset = my - this.scrollbarY;
            return true;
        } else {
            this.scrollbarHover = false;
        }

        // If mouse is over items
        if (
            mx > this.x + this.toolbarWidth &&
            mx < this.x + this.w - this.scrollbarWidth &&
            my > this.y &&
            my < this.y + this.h
        ) {
            const itemIndex = Math.floor((my - this.y) / this.itemHeight) + this.scrollOffset;

            const level = this.folderHistory.length;
            const appendToQueue = this.addMode || options.addToQueue === true;

            //Clicked on root level, (A,B,C, etc)
            if(itemIndex<this.totalItems && level===0){
                this.selectedIndex=itemIndex;
                const item = this.items[itemIndex];
                if(!item){
                    return true;
                }

                if(item.type==='folder'){ //load folder array
                    if (appendToQueue) {
                        this.addFolderToQueue(item);
                        return true;
                    }

                    //clear items and load new items from  items.indexes[itemIndex].id
                    //this.items=[{name:'Loading'}]; //clear items array
                    this.items=Array.isArray(item.artists) ? item.artists : []; //load artists array
                    this.totalItems=this.items.length;
                    this.scrollOffset=0; //reset offset
                    this.selectedIndex=0; //reset selected index
                    this.folderHistory.push(itemIndex); //This is a sort of exception, sice Artists are NOT folders, but we need to store something for navigation


                }else if(item.type==='song'){ //play song located in root
                    if (appendToQueue) {
                        this.addSongToQueue(item);
                        return true;
                    }

                    if(item.id && this.playerObj){
                        this.playerObj.playSongById(item.id);
                    }
                }
                return true;
            }


            //Clicked on a folder or song inside a folder
            else if(itemIndex<this.totalItems && level>0){
               this.selectedIndex=itemIndex;
                const item = this.items[itemIndex];
                if(!item){
                    return true;
                }

                const itemId = item.id;
                //If it's a song, play it
                if(item.type==='song'){
                    if (appendToQueue) {
                        this.addSongToQueue(item);
                        return true;
                    }

                    if(this.playerObj){
                        this.playerObj.stopSong(); //stop current song if any
                    }
                    //loadAndPlaySong(itemId);
                    this.songsList.clear(); //clear current playlist
                    this.songsList.addSong(item); //add seclected song to playlist
                    this.songsList.setPointer(0); //set pointer to first song
                    //add this and the rest of the songs in the current folder to the playlist
                    for(let i=itemIndex+1; i<this.totalItems; i++){
                        if(this.items[i].type==='song'){
                            this.songsList.addSong(this.items[i]);
                        }
                    }
                    if(item.id && this.playerObj){
                        this.playerObj.playSongById(item.id); //play the song
                    }

                }
                else{
                    if (appendToQueue) {
                        this.addFolderToQueue(item);
                        return true;
                    }

                 //obtain only the folder information
                    if(itemId){
                        this.loadMusicDirectory(itemId); //load music directory for the selected folder
                    }
                }
                return true;

            }

        }

        return false;
    }

    /**
     * Toggles append mode for visible browser song clicks.
     * Normal mode keeps the existing play-now behavior; add mode appends the
     * clicked song to QUEUE without interrupting playback.
     */
    toggleAddMode() {
        this.addMode = !this.addMode;
        if (this.telemetry) {
            this.telemetry.emit("QUEUE", `Add mode :: ${this.addMode ? "enabled" : "disabled"}`, {
                key: "browser-add-mode",
                dedupe: true
            });
        }
    }

    /**
     * Appends a browser song item to the local queue without starting playback.
     * Used by Shift+Click and by the toolbar add mode.
     * @param {Object} item - Browser item representing a song.
     */
    addSongToQueue(item) {
        if (!item || item.type !== "song" || !this.songsList || typeof this.songsList.addSong !== "function") {
            return;
        }

        this.songsList.addSong(item);
        this.emitSongAdded(item);
    }

    /**
     * Appends every song found inside a browser folder to the local queue.
     * Folder expansion is recursive so album/artist containers can be queued
     * from the same add mode used for individual tracks.
     * @param {Object} item - Browser item representing a folder-like row.
     */
    async addFolderToQueue(item) {
        if (!item || item.type === "song" || !this.songsList || typeof this.songsList.addSongsList !== "function") {
            return;
        }

        const folderName = item.name || item.title || "Untitled folder";
        if (this.telemetry) {
            this.telemetry.emit("QUEUE", `Scanning folder :: ${folderName}`);
        }

        const songs = await this.collectSongsFromFolder(item);
        // Batch append avoids rebuilding playlist random state once per track
        // when a large folder is sent to the queue.
        this.songsList.addSongsList(songs);

        if (this.telemetry) {
            this.telemetry.emit("QUEUE", `Added folder :: ${folderName} :: ${songs.length} tracks`);
        }
    }

    /**
     * Emits a DATA FEED event for an appended track.
     * @param {Object} item - Browser song item.
     */
    emitSongAdded(item) {
        if (!this.telemetry || !item) {
            return;
        }

        const artist = item.artist || "Unknown artist";
        const title = item.title || item.name || "Untitled";
        this.telemetry.emit("QUEUE", `Added track :: ${artist} - ${title}`);
    }

    /**
     * Recursively reads Subsonic folder children and returns queue-ready songs.
     * The visited set prevents accidental cycles or repeated directory IDs from
     * expanding forever if the server returns unusual directory data.
     * @param {Object} item - Folder-like browser item.
     * @param {Set<string>} visited - Directory IDs already scanned.
     * @returns {Promise<Array>} Queue-ready song items.
     */
    async collectSongsFromFolder(item, visited = new Set()) {
        if (!item) {
            return [];
        }

        if (item.type === "song") {
            return [item];
        }

        if (Array.isArray(item.artists)) {
            const collected = [];
            for (const artist of item.artists) {
                collected.push(...await this.collectSongsFromFolder(artist, visited));
            }
            return collected;
        }

        if (!item.id || visited.has(item.id)) {
            return [];
        }

        visited.add(item.id);
        const children = await this.subsonicObj.getMusicDirectory(item.id);
        const collected = [];
        for (const child of children) {
            if (!child) {
                continue;
            }

            const childItem = this.createBrowserItemFromDirectoryChild(child);
            if (childItem.type === "song") {
                collected.push(childItem);
            } else {
                collected.push(...await this.collectSongsFromFolder(childItem, visited));
            }
        }

        return collected;
    }

    /**
     * Builds the visible browser row label with a type glyph.
     * Items without an explicit song type are treated as folders because
     * Subsonic artist/index rows navigate like containers in this browser.
     * @param {Object|null} item - Browser row item.
     * @returns {string} Display label with icon prefix.
     */
    getItemDisplayLabel(item) {
        const icon = item?.type === "song" ? this.songIcon : this.folderIcon;
        const name = item?.name || item?.title || "Untitled";
        return `${icon} ${name}`;
    }

    /**
     * Converts a Subsonic directory child into the browser item shape.
     * Keeping this mapping in one place lets drawing, navigation, and recursive
     * queue appends use the same folder/song metadata.
     * @param {Object} child - Raw Subsonic directory child.
     * @returns {Object} Browser item.
     */
    createBrowserItemFromDirectoryChild(child) {
        const name = child.title || child.name || "Untitled";
        return {
            name: name,
            id: child.id,
            type: child.isDir ? "folder" : "song",
            album: child.album,
            albumId: child.albumId,
            artist: child.artist,
            artistId: child.artistId,
            coverArt: child.coverArt,
            parent: child.parent,
            title: child.title,
        };
    }

    /**
     * Handles mouse dragged events for the scrollbar.
     * Updates the scrollbar position and scroll offset based on mouse movement.
     * @param {number} mx - The x-coordinate of the mouse drag.
     * @param {number} my - The y-coordinate of the mouse drag.
     */
    handleMouseDrag(mx, my) {
        if (this.scrollbarDragging) {
            this.visibleItems = Math.floor(this.h / this.itemHeight);
            let maxScrollY = this.y + this.h - this.scrollbarHeight;

            // Calculate the new Y position of the scrollbar
            let newY = my - this.scrollbarDragOffset;

            // Clamp the scrollbar position to stay within bounds
            newY = Math.max(this.y, Math.min(newY, maxScrollY));
            this.scrollbarY = newY;

            // Update the scroll offset based on the scrollbar position
            this.scrollOffset = Math.round(
                ((this.scrollbarY - this.y) / (this.h - this.scrollbarHeight)) * (this.items.length - this.visibleItems)
            );

            // Ensure the scroll offset stays within bounds
            this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, this.items.length - this.visibleItems));
        }
    }

    /**
     * Tests whether the pointer is inside the scrollable browser item area.
     * The toolbar is excluded so wheel input over toolbar buttons does not
     * accidentally scroll the item list.
     * @param {number} mx - Pointer x coordinate.
     * @param {number} my - Pointer y coordinate.
     * @returns {boolean} True when the pointer is inside the browser list.
     */
    containsScrollableArea(mx, my) {
        return mx >= this.x + this.toolbarWidth &&
            mx <= this.x + this.w &&
            my >= this.y &&
            my <= this.y + this.h;
    }

    /**
     * Handles mouse wheel scrolling over the file browser list.
     * @param {number} delta - Mouse wheel delta from p5's wheel event.
     */
    handleMouseWheel(delta) {
        this.visibleItems = Math.floor(this.h / this.itemHeight);
        this.totalItems = this.items.length;
        if (this.totalItems <= this.visibleItems) {
            return;
        }

        // Wheel direction follows the same convention as playlist and DATA FEED:
        // positive deltas move down through the list, negative deltas move up.
        this.scrollOffset += delta > 0 ? 1 : -1;
        this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, this.totalItems - this.visibleItems));
    }

    /**
     * Handles mouse released events.
     * Stops dragging the scrollbar.
     */
    handleMouseReleased() {
        this.scrollbarDragging=false;
    }

    getLayoutBounds() {
        return { x: this.x, y: this.y, w: this.w, h: this.h };
    }

    moveTo(x, y) {
        this.x = x;
        this.y = y;
    }

    /**
     * Fits the browser list inside its owning panel body.
     * The header area remains available for the panel title and resize handle.
     * @param {Object} panel - Layout panel bounds.
     */
    fitToPanel(panel) {
        this.x = panel.x + 12;
        this.y = panel.y + 30;
        this.w = Math.max(150, panel.w - 24);
        this.h = Math.max(70, panel.h - 42);
        this.clampScrollOffset();
    }

    /**
     * Minimum browser panel size used by LayoutManager resize handles.
     * @returns {Object} Minimum width and height.
     */
    getMinPanelSize() {
        return { w: 190, h: 125 };
    }

    /**
     * Keeps the browser viewport inside the legal row range after resize or
     * navigation changes.
     */
    clampScrollOffset() {
        const visibleItems = Math.floor(this.h / this.itemHeight);
        const maxOffset = Math.max(0, this.items.length - visibleItems);
        this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, maxOffset));
    }

    /**
     * Loads the root-level indexes from the Subsonic API and populates the items array.
     * This includes the "A, B, C..." level and associated artists or songs.
     * Resets the file browser state.
     * @async
     */
    async loadIndexes() {
        this.items = []; // clear items array
        this.totalItems = 0; // reset total items

        const indexes = await this.subsonicObj.getIndexes();
        const indexItems = indexes?.index || [];
        const childItems = indexes?.child || [];

        if (indexItems.length > 0) {
            for (const index of indexItems) {
                if(!index){
                    continue;
                }

                const name = index.name || "Untitled";
                const id = index.id;
                const artists = Array.isArray(index.artist) ? index.artist : (index.artist ? [index.artist] : []);
                this.items.push({ name: name, id: id, type: 'folder', artists: artists });
            }
        }
        if (childItems.length > 0) {
            for (const child of childItems) {
                if(!child){
                    continue;
                }

                const name = child.title || child.name || "Untitled";
                const id = child.id;
                this.items.push({ name: name, id: id, type: 'song' });
            }
        }

        this.totalItems = this.items.length;
        console.log("FileBrowser: Loaded indexes");
    }

    /**
     * Loads a music directory from the Subsonic API and populates the items array.
     * Updates the file browser to display the contents of the specified folder.
     * @param {string} id - The ID of the folder to load.
     * @async
     */
    async loadMusicDirectory(id) {
        const directory = await this.subsonicObj.getMusicDirectory(id);

        this.scrollOffset = 0; // reset offset
        this.selectedIndex = 0; // reset selected index
        this.totalItems = 0; // reset total items
        this.items = []; // clear items array
        if (directory.length > 0) {
            for (const child of directory) {
                if(!child){
                    continue;
                }

                this.items.push(this.createBrowserItemFromDirectoryChild(child));
            }
        }
        this.totalItems = this.items.length;
        this.scrollOffset = 0; // reset offset
        this.selectedIndex = 0; // reset selected index
        console.log("FileBrowser: Loaded music directory for id " + id);

        // Update navigation history
        this.folderHistory.push(id);
    }



    /**
     * Navigates back to the previous folder in the navigation history.
     * If at the root level, reloads the root indexes.
     * @async
     */
    async navigateBack() {
        var selected=0;
        if (this.folderHistory.length > 2) {
            // Remove the current folder ID from the history
            this.folderHistory.pop();

            // Get the previous folder ID
            const previousFolderId = this.folderHistory[this.folderHistory.length - 1];

            // Load the previous folder
            await this.loadMusicDirectory(previousFolderId);

            this.folderHistory.pop(); // Remove it again since it will be added again in loadMusicDirectory

            console.log(`FileBrowser: Navigated back to folder id ${previousFolderId}`);
        } else if (this.folderHistory.length === 2) {
            // Remove the current folder ID from the history
            this.folderHistory.pop();
            selected =this.folderHistory[0]; // Get the index of the artist level
            await this.loadIndexes(); // Load the root level
            // Set the selected index to the artist level
            const item = this.items[selected];
            this.items=Array.isArray(item?.artists) ? item.artists : []; //load artists array
            this.totalItems=this.items.length;


            console.log("FileBrowser: Navigated back to the artist level");
        } else{
            this.folderHistory = []; // Clear history
            this.selectedIndex=selected;
            this.scrollOffset=selected;
            await this.loadIndexes(); // Reload the root level
            console.log("FileBrowser: Navigated back to the ABC level");

        }
    }
}

/* ---- lib/audioeffects.js ---- */
/**
 * Audio effects and output routing for Subsonic Neon Deck.
 *
 * AudioEffects owns the WebAudio/p5.sound nodes used for volume, balance,
 * playback rate, three-band filtering, and reverb. The sketch still owns the
 * UI sliders and passes their values in as plain data each frame.
 */
class AudioEffects {
    constructor() {
        // The current song and filter state are cached so routing is rebuilt
        // only when the source or filter switch changes.
        this.song = null;
        this.filtersOn = true;
        this.routedSong = null;
        this.routedFiltersState = null;

        // Parallel EQ buses. Each band-pass feeds its own gain node and then
        // returns to the p5 master output.
        this.bassGain = new p5.Gain();
        this.midGain = new p5.Gain();
        this.trebleGain = new p5.Gain();

        this.bassFilter = new p5.BandPass();
        this.bassFilter.freq(100);
        this.bassFilter.res(0.2);

        this.midFilter = new p5.BandPass();
        this.midFilter.freq(2000);
        this.midFilter.res(0.4);

        this.trebleFilter = new p5.BandPass();
        this.trebleFilter.freq(12000);
        this.trebleFilter.res(0.4);

        // PERF PATCH [lazy-reverb-route]: create reverb only when the filter
        // bus is enabled. Firefox profiles showed GraphRunner doing expensive
        // WebAudio work, so direct routes should not keep convolver paths live.
        this.reverb = null;

        this.resetAppliedValues();
    }

    configure(song, filtersOn, force = false, controls = {}) {
        if (!song) {
            this.clearRouting();
            return;
        }

        this.song = song;
        this.filtersOn = !!filtersOn;

        if (!force && this.routedSong === song && this.routedFiltersState === this.filtersOn) {
            return;
        }

        this.rebuildRouting(controls);
        this.routedSong = song;
        this.routedFiltersState = this.filtersOn;
        this.resetAppliedValues();
    }

    /**
     * Releases the current song routing while the player has no active source.
     * Used during track handoff so old decoded buffers and FX nodes are not
     * kept reachable while the next stream is loading.
     */
    clearRouting() {
        if (!this.song && !this.routedSong) {
            return;
        }

        // PERF PATCH [fx-route-handoff-release]: when Player detaches a song,
        // the FX graph must drop references too or WebAudio can keep the old
        // decoded buffer reachable until the next routing rebuild.
        this.disconnectNode(this.song);
        this.disconnectNode(this.bassFilter);
        this.disconnectNode(this.midFilter);
        this.disconnectNode(this.trebleFilter);
        this.disconnectNode(this.bassGain);
        this.disconnectNode(this.midGain);
        this.disconnectNode(this.trebleGain);
        this.disposeNode(this.reverb);
        this.reverb = null;
        this.song = null;
        this.routedSong = null;
        this.routedFiltersState = null;
        this.resetAppliedValues();
    }

    /**
     * Rebuilds the current song's WebAudio routing.
     * PERF PATCH [lazy-reverb-route]: the direct route avoids p5.Reverb and
     * its convolver worker when filters are disabled, keeping Firefox's
     * GraphRunner graph as small as possible during long sessions.
     * @param {Object} controls - Current UI control values for initial FX state.
     */
    rebuildRouting(controls = {}) {
        this.disconnectNode(this.song);
        this.disconnectNode(this.bassFilter);
        this.disconnectNode(this.midFilter);
        this.disconnectNode(this.trebleFilter);
        this.disconnectNode(this.bassGain);
        this.disconnectNode(this.midGain);
        this.disconnectNode(this.trebleGain);
        this.disposeNode(this.reverb);
        this.reverb = null;

        if (this.filtersOn) {
            this.song.connect(this.bassFilter);
            this.bassFilter.connect(this.bassGain);
            this.bassGain.connect();

            this.song.connect(this.midFilter);
            this.midFilter.connect(this.midGain);
            this.midGain.connect();

            this.song.connect(this.trebleFilter);
            this.trebleFilter.connect(this.trebleGain);
            this.trebleGain.connect();

            this.reverb = this.createReverb();
            this.reverb.process(this.song, 3, 2);
            this.reverb.drywet(controls.reverbMix || 0);
            this.reverb.amp(controls.reverbVolume || 0);
        } else {
            this.song.connect();
        }
    }

    /**
     * Creates a fresh p5.Reverb instance for the active FX route.
     * PERF PATCH [lazy-reverb-route]: p5.Reverb owns convolver resources, so
     * the app creates it only for enabled FX graphs and disposes it on rebuild.
     * @returns {p5.Reverb} A new reverb node for the current route.
     */
    createReverb() {
        return new p5.Reverb();
    }

    applyControls(controls = {}) {
        if (!this.song) {
            return;
        }

        this.applyVolume(controls.volume);
        this.applyPan(controls.pan);
        this.applyRate(controls.rate);
        this.applyFilterValues(controls);
    }

    applyVolume(value) {
        if (value === undefined || !this.valueChanged(value, this.lastVolumeValue)) {
            return;
        }

        // Slider travel is mapped to a logarithmic-feeling curve so the low
        // half of the control is usable instead of feeling almost silent.
        const volume = -Math.log10(1 - value * 0.9);
        this.song.setVolume(volume, 0.03);
        this.lastVolumeValue = value;
    }

    applyPan(value) {
        if (value === undefined || !this.valueChanged(value, this.lastPanValue)) {
            return;
        }

        this.song.pan(value);
        this.lastPanValue = value;
    }

    applyRate(value) {
        if (value === undefined || !this.valueChanged(value, this.lastRateValue)) {
            return;
        }

        this.song.rate(value);
        this.lastRateValue = value;
    }

    applyFilterValues(controls) {
        if (controls.bass !== undefined && this.valueChanged(controls.bass, this.lastBassValue)) {
            this.bassGain.amp(controls.bass, 0.03);
            this.lastBassValue = controls.bass;
        }

        if (controls.mid !== undefined && this.valueChanged(controls.mid, this.lastMidValue)) {
            this.midGain.amp(controls.mid, 0.03);
            this.lastMidValue = controls.mid;
        }

        if (controls.treble !== undefined && this.valueChanged(controls.treble, this.lastTrebleValue)) {
            this.trebleGain.amp(controls.treble, 0.03);
            this.lastTrebleValue = controls.treble;
        }

        if (this.reverb && controls.reverbMix !== undefined && this.valueChanged(controls.reverbMix, this.lastReverbValue)) {
            this.reverb.drywet(controls.reverbMix);
            this.lastReverbValue = controls.reverbMix;
        }

        if (this.reverb && controls.reverbVolume !== undefined && this.valueChanged(controls.reverbVolume, this.lastReverbVolValue)) {
            this.reverb.amp(controls.reverbVolume, 0.03);
            this.lastReverbVolValue = controls.reverbVolume;
        }
    }

    resetAppliedValues() {
        this.lastVolumeValue = null;
        this.lastPanValue = null;
        this.lastRateValue = null;
        this.lastBassValue = null;
        this.lastMidValue = null;
        this.lastTrebleValue = null;
        this.lastReverbValue = null;
        this.lastReverbVolValue = null;
    }

    valueChanged(current, previous) {
        return previous === null || Math.abs(current - previous) > 0.0001;
    }

    disconnectNode(node) {
        try {
            if (node) {
                node.disconnect();
            }
        } catch (error) {
            // Some p5/WebAudio nodes throw when already disconnected.
        }
    }

    disposeNode(node) {
        // PERF PATCH [fx-route-handoff-release]: dispose nodes we replace
        // completely. p5.sound keeps objects in soundArray, and dispose()
        // releases internal buffers/nodes so old FX graphs do not accumulate.
        try {
            if (node && typeof node.dispose === "function") {
                node.dispose();
                return;
            }
        } catch (error) {
            // Fall back to disconnect below.
        }

        this.disconnectNode(node);
    }
}

/* ---- lib/layoutmanager.js ---- */
/**
 * Layout editor and persistence model for the canvas deck.
 *
 * LayoutManager intentionally works with generic layout items:
 * { key, x, y, w, h, moveTo() }. It does not know about sliders,
 * visualizers, DOM buttons, or p5 controls; the sketch provides those
 * adapters and the manager owns panel movement, resizing, and ownership.
 */
class LayoutManager {
    static getDefaultPanels() {
        // Add new deck panels here. This is the single source for default
        // panel geometry; saved layouts may override these values at runtime.
        const panels = [
            { key: "nowPlaying", x: 270, y: 26, w: 370, h: 165, label: "NOW PLAYING", accent: "line" },
            { key: "source", x: 12, y: 279, w: 235, h: 125, label: "SOURCE", accent: "pink" },
            { key: "transport", x: 122, y: 27, w: 145, h: 150, label: "TRANSPORT", accent: "amber" },
            { key: "spectrum", x: 12, y: 520, w: 220, h: 144, label: "SPECTRUM", accent: "line" },
            { key: "waveform", x: 238, y: 520, w: 220, h: 144, label: "WAVEFORM", accent: "pink" },
            { key: "position", x: 125, y: 198, w: 516, h: 73, label: "POSITION", accent: "amber" },
            { key: "vuMeters", x: 627, y: 520, w: 124, h: 149, label: "VU METERS", accent: "line" },
            { key: "level", x: 646, y: 25, w: 90, h: 245, label: "LEVEL", accent: "amber" },
            { key: "fxBus", x: 825, y: 279, w: 420, h: 215, label: "FX BUS", accent: "line" },
            { key: "phase", x: 465, y: 520, w: 156, h: 145, label: "PHASE", accent: "pink" },
            { key: "browser", x: 252, y: 279, w: 280, h: 235, label: "BROWSER", accent: "pink" },
            { key: "queue", x: 540, y: 279, w: 280, h: 235, label: "QUEUE", accent: "line" },
            { key: "dataFeed", x: 740, y: 23, w: 499, h: 247, label: "DATA FEED", accent: "pink" },
            { key: "layoutTools", x: 13, y: 27, w: 104, h: 210, label: "USER CONTROL", accent: "amber" }
        ];

        // Return fresh objects so runtime edits never mutate the defaults.
        return panels.map((panel) => ({ ...panel }));
    }

    constructor(panelLayout, options = {}) {
        // Panels are the actual mutable layout rectangles. Default panel
        // geometry comes from getDefaultPanels(), then this manager owns
        // runtime edits to it.
        this.panelLayout = panelLayout;

        // The sketch supplies live adapters because only it knows the concrete
        // components. LayoutManager only asks for generic bounds/moveTo items.
        this.getMovableLayoutItems = options.getMovableLayoutItems;
        this.getPanelBoundLayoutItems = options.getPanelBoundLayoutItems;
        this.getPanelBoundComponent = options.getPanelBoundComponent;
        this.isMovePanelsEnabled = options.isMovePanelsEnabled;
        this.isMoveElementsEnabled = options.isMoveElementsEnabled;

        // Panel-bound components such as spectrum and waveform must re-fit
        // themselves whenever their panel changes size or position.
        this.onPanelChanged = options.onPanelChanged || (() => {});
        this.onSaveRequested = options.onSaveRequested || (() => {});

        // Active drag state. dragChildren stores the panel-owned elements that
        // should move together with a dragged panel.
        this.dragItem = null;
        this.dragOffsetX = 0;
        this.dragOffsetY = 0;
        this.dragStartX = 0;
        this.dragStartY = 0;
        this.dragChildren = [];

        // Explicit ownership prevents overlapping panels from stealing controls
        // just because their rectangles intersect during a move.
        this.itemPanelOwners = {};

        // Active resize state for panel lower-right handles.
        this.resizePanel = null;
        this.resizeStartMouseX = 0;
        this.resizeStartMouseY = 0;
        this.resizeStartW = 0;
        this.resizeStartH = 0;
    }

    getPanels() {
        return this.panelLayout;
    }

    // ##SKINNY MODE
    // Drawable panels are the panels whose bound component is active. This lets
    // a visualizer hide its whole panel by exposing isInactive(), while normal
    // control panels keep drawing because they have no inactive-aware component.
    getDrawablePanels() {
        return this.panelLayout.filter((panel) => !this.isPanelInactive(panel));
    }

    // ##SKINNY MODE
    // Interactive panels follow the same rule as drawable panels: if the user
    // cannot see a visualizer panel, layout editing should not grab or resize it.
    getInteractivePanels() {
        return this.getDrawablePanels();
    }

    // ##SKINNY MODE
    // LayoutManager does not own component state. It asks the sketch for the
    // component bound to a panel, then trusts that component's inactive flag.
    isPanelInactive(panel) {
        const component = this.getPanelBoundComponent ? this.getPanelBoundComponent(panel) : null;
        return this.isComponentInactive(component);
    }

    isComponentInactive(component) {
        return !!(component && typeof component.isInactive === "function" && component.isInactive());
    }

    isLayoutEditMode() {
        return this.isMovePanelsOn() || this.isMoveElementsOn();
    }

    isMovePanelsOn() {
        return !!(this.isMovePanelsEnabled && this.isMovePanelsEnabled());
    }

    isMoveElementsOn() {
        return !!(this.isMoveElementsEnabled && this.isMoveElementsEnabled());
    }

    getStatusText() {
        if (this.isMovePanelsOn() && this.isMoveElementsOn()) {
            return "LAYOUT: move panels and elements";
        }
        if (this.isMovePanelsOn()) {
            return "LAYOUT: move panels";
        }
        if (this.isMoveElementsOn()) {
            return "LAYOUT: move elements";
        }
        return "LAYOUT LOCKED";
    }

    drawOverlay() {
        if (!this.isLayoutEditMode()) {
            return;
        }

        push();
        noFill();
        strokeWeight(1);

        if (this.isMovePanelsOn()) {
            stroke(UI.line[0], UI.line[1], UI.line[2], 145);
            // Inactive visualizer panels are omitted from the edit overlay so
            // the visible layout matches the actual editable surface.
            for (const panel of this.getDrawablePanels()) {
                rect(panel.x, panel.y, panel.w, panel.h, 4);
            }
        }

        if (this.isMoveElementsOn()) {
            stroke(UI.amber[0], UI.amber[1], UI.amber[2], 135);
            for (const item of this.getMovables()) {
                rect(item.x, item.y, item.w, item.h, 3);
            }
        }

        if (this.isMovePanelsOn() && this.isMoveElementsOn()) {
            stroke(UI.pink[0], UI.pink[1], UI.pink[2], 120);
        }
        for (const item of this.getPanelBoundItems()) {
            rect(item.x, item.y, item.w, item.h, 3);
        }

        noStroke();
        fill(246, 200, 95);
        textSize(11);
        textAlign(RIGHT, TOP);
        text(this.getStatusText(), width - 24, 8);
        pop();
    }

    isResizablePanel(panel) {
        // ##SKINNY MODE
        // Resizing an inactive visualizer panel would be invisible and
        // confusing, so hidden panels are treated as non-interactive.
        return panel && !this.isPanelInactive(panel) &&
            (panel.key === "spectrum" || panel.key === "waveform" || panel.key === "vuMeters" || panel.key === "phase" || panel.key === "position" || panel.key === "browser" || panel.key === "queue" || panel.key === "dataFeed");
    }

    isPointInResizeHandle(mx, my, panel) {
        return this.isResizablePanel(panel) &&
            mx >= panel.x + panel.w - 22 &&
            mx <= panel.x + panel.w &&
            my >= panel.y + panel.h - 22 &&
            my <= panel.y + panel.h;
    }

    handleResizeMousePressed(mx, my) {
        if (!this.isMovePanelsOn()) {
            return false;
        }

        // Search from topmost to bottommost panel so overlapping panels behave
        // like the drawn stack.
        const panels = this.getInteractivePanels();
        for (let i = panels.length - 1; i >= 0; i--) {
            const panel = panels[i];
            if (this.isPointInResizeHandle(mx, my, panel)) {
                this.resizePanel = panel;
                this.resizeStartMouseX = mx;
                this.resizeStartMouseY = my;
                this.resizeStartW = panel.w;
                this.resizeStartH = panel.h;
                return true;
            }
        }

        return false;
    }

    handleResizeMouseDragged(mx, my) {
        if (!this.isMovePanelsOn() || !this.resizePanel) {
            return false;
        }

        // Minimum sizes are delegated to the panel-bound component whenever
        // possible, so component-specific geometry stays in that module.
        const minSize = this.getResizablePanelMinSize(this.resizePanel);
        this.resizePanel.w = Math.round(constrain(this.resizeStartW + mx - this.resizeStartMouseX, minSize.w, width - this.resizePanel.x));
        this.resizePanel.h = Math.round(constrain(this.resizeStartH + my - this.resizeStartMouseY, minSize.h, height - this.resizePanel.y));
        this.onPanelChanged(this.resizePanel);
        return true;
    }

    getResizablePanelMinSize(panel) {
        const component = this.getPanelBoundComponent ? this.getPanelBoundComponent(panel) : null;
        if (component && typeof component.getMinPanelSize === "function") {
            return component.getMinPanelSize();
        }

        return { w: 220, h: 120 };
    }

    handleResizeMouseReleased() {
        if (!this.isMovePanelsOn() || !this.resizePanel) {
            return false;
        }

        console.log("Panel resized:", this.resizePanel.key, {
            x: this.resizePanel.x,
            y: this.resizePanel.y,
            w: this.resizePanel.w,
            h: this.resizePanel.h
        });
        this.logFullLayout();
        this.resizePanel = null;
        return true;
    }

    createMovableItem(key, bounds, moveTo, data = null) {
        // Generic shape used everywhere in the layout editor. Any component can
        // participate as long as the sketch can provide bounds and a moveTo.
        return {
            key,
            x: bounds.x,
            y: bounds.y,
            w: bounds.w,
            h: bounds.h,
            moveTo,
            data
        };
    }

    getMovablePanelItems() {
        // Panel dragging uses only interactive panels. Hidden visualizer panels
        // keep their saved/default coordinates, but they cannot be grabbed.
        return this.getInteractivePanels().map((panel) => this.createMovableItem(`panel:${panel.key}`, panel, (x, y, item) => {
            this.movePanelTo(item.data, x, y);
        }, panel));
    }

    getAllPanelLayoutItems() {
        // ##SKINNY MODE
        // Full-layout serialization must include hidden panels too, otherwise
        // toggling Skinny mode on could accidentally erase their layout defaults.
        return this.panelLayout.map((panel) => this.createMovableItem(`panel:${panel.key}`, panel, (x, y, item) => {
            this.movePanelTo(item.data, x, y);
        }, panel));
    }

    movePanelTo(panel, x, y) {
        panel.x = x;
        panel.y = y;
        this.onPanelChanged(panel);
    }

    handleItemMousePressed(mx, my) {
        if (!this.isLayoutEditMode()) {
            return false;
        }

        if (this.isMovePanelsOn()) {
            // Panel headers win over controls inside the same panel. This keeps
            // compact panels draggable even when their content fills the body.
            const panelItems = this.getMovablePanelItems();
            const headerPanelItem = this.findPanelHeaderLayoutItem(mx, my, panelItems);
            if (headerPanelItem) {
                this.startDrag(headerPanelItem, mx, my);
                return true;
            }
        }

        if (!this.isMoveElementsOn()) {
            return false;
        }

        const items = this.getMovables();
        for (let i = 0; i < items.length; i++) {
            const item = items[i];
            if (mx >= item.x && mx <= item.x + item.w && my >= item.y && my <= item.y + item.h) {
                this.startDrag(item, mx, my);
                return true;
            }
        }

        if (this.isMovePanelsOn()) {
            const panelItems = this.getMovablePanelItems();
            for (let i = panelItems.length - 1; i >= 0; i--) {
                const item = panelItems[i];
                if (mx >= item.x && mx <= item.x + item.w && my >= item.y && my <= item.y + item.h) {
                    this.startDrag(item, mx, my);
                    return true;
                }
            }
        }

        return false;
    }

    findPanelHeaderLayoutItem(mx, my, items) {
        for (let i = items.length - 1; i >= 0; i--) {
            const item = items[i];
            if (!item.key || item.key.indexOf("panel:") !== 0) {
                continue;
            }

            const inHeader = mx >= item.x && mx <= item.x + item.w && my >= item.y && my <= item.y + 22;
            if (inHeader) {
                return item;
            }
        }

        return null;
    }

    startDrag(item, mx, my) {
        this.dragItem = item;
        this.dragOffsetX = mx - item.x;
        this.dragOffsetY = my - item.y;
        this.dragStartX = item.x;
        this.dragStartY = item.y;
        this.dragChildren = this.getDragChildren(item);
    }

    getDragChildren(item) {
        if (!item.key || item.key.indexOf("panel:") !== 0) {
            return [];
        }

        // Children are selected by persisted ownership, not visual overlap.
        // This is the key rule that makes panels behave like containers.
        const panelKey = item.key.slice("panel:".length);
        return this.getMovables()
            .filter((candidate) => this.itemPanelOwners[candidate.key] === panelKey)
            .map((candidate) => ({
                item: candidate,
                startX: candidate.x,
                startY: candidate.y
            }));
    }

    initializeOwners(savedOwners = null) {
        this.itemPanelOwners = {};
        if (savedOwners && typeof savedOwners === "object") {
            this.itemPanelOwners = { ...savedOwners };
        }

        // New controls introduced after an older saved layout get assigned to
        // the panel that currently contains their center.
        for (const item of this.getMovables()) {
            if (!(item.key in this.itemPanelOwners)) {
                this.itemPanelOwners[item.key] = this.getContainingPanelKey(item);
            }
        }
    }

    getContainingPanelKey(item) {
        // Topmost matching panel wins when an element is centered inside
        // overlapping panels.
        const panels = this.getInteractivePanels();
        for (let i = panels.length - 1; i >= 0; i--) {
            const panel = panels[i];
            const panelItem = { x: panel.x, y: panel.y, w: panel.w, h: panel.h };
            if (this.isLayoutItemInsidePanel(item, panelItem)) {
                return panel.key;
            }
        }

        return null;
    }

    updateItemPanelOwner(item) {
        if (!item || !item.key || item.key.indexOf("panel:") === 0) {
            return;
        }

        this.itemPanelOwners[item.key] = this.getContainingPanelKey(item);
    }

    isLayoutItemInsidePanel(item, panelItem) {
        const centerX = item.x + item.w / 2;
        const centerY = item.y + item.h / 2;
        return centerX >= panelItem.x &&
            centerX <= panelItem.x + panelItem.w &&
            centerY >= panelItem.y &&
            centerY <= panelItem.y + panelItem.h;
    }

    handleItemMouseDragged(mx, my) {
        if (!this.isLayoutEditMode() || !this.dragItem) {
            return false;
        }

        // Drag coordinates are clamped to the current canvas. Saved fullscreen
        // layouts can still restore outside a smaller viewport; this clamp only
        // applies while actively editing in the current viewport.
        const x = Math.round(constrain(mx - this.dragOffsetX, 0, width - this.dragItem.w));
        const y = Math.round(constrain(my - this.dragOffsetY, 0, height - this.dragItem.h));
        this.dragItem.moveTo(x, y, this.dragItem);
        this.dragItem.x = x;
        this.dragItem.y = y;

        if (this.dragChildren.length > 0) {
            const dx = x - this.dragStartX;
            const dy = y - this.dragStartY;
            // Preserve each child's original offset relative to the panel at
            // the moment the panel drag started.
            for (const child of this.dragChildren) {
                const childX = Math.round(constrain(child.startX + dx, 0, width - child.item.w));
                const childY = Math.round(constrain(child.startY + dy, 0, height - child.item.h));
                child.item.moveTo(childX, childY, child.item);
                child.item.x = childX;
                child.item.y = childY;
            }
        }

        return true;
    }

    handleItemMouseReleased() {
        if (!this.isLayoutEditMode() || !this.dragItem) {
            return false;
        }

        console.log("Layout item moved:", this.dragItem.key, {
            x: this.dragItem.x,
            y: this.dragItem.y,
            w: this.dragItem.w,
            h: this.dragItem.h
        });
        this.updateItemPanelOwner(this.dragItem);
        this.logFullLayout();
        this.dragItem = null;
        this.dragChildren = [];
        return true;
    }

    getPanelLayout() {
        return this.panelLayout.map((panel) => ({
            key: panel.key,
            x: panel.x,
            y: panel.y,
            w: panel.w,
            h: panel.h
        }));
    }

    logPanelLayout() {
        console.log("Panel layout JSON:", JSON.stringify(this.getPanelLayout(), null, 2));
    }

    getFullLayout() {
        // The persisted layout combines panel rectangles and movable item
        // rectangles. Runtime-only callbacks/data are intentionally omitted.
        return this.getAllPanelLayoutItems().concat(this.getMovables()).map((item) => ({
            key: item.key,
            x: Math.round(item.x),
            y: Math.round(item.y),
            w: Math.round(item.w),
            h: Math.round(item.h)
        }));
    }

    logFullLayout() {
        console.log("Full layout JSON:", JSON.stringify(this.getFullLayout(), null, 2));
    }

    getMovables() {
        return this.getMovableLayoutItems ? this.getMovableLayoutItems() : [];
    }

    getPanelBoundItems() {
        const items = this.getPanelBoundLayoutItems ? this.getPanelBoundLayoutItems() : [];
        // ##SKINNY MODE
        // Panel-bound component hitboxes are used for overlay/hit testing.
        // Skip inactive visualizers so hidden plots do not leave ghost handles.
        return items.filter((item) => {
            const panel = this.panelLayout.find((candidate) => candidate.key === item.key);
            return !panel || !this.isPanelInactive(panel);
        });
    }
}

/* ---- lib/playercontrol.js ---- */
/**
 * Transport controls for the player.
 *
 * This class owns the p5-created DOM image buttons used by the TRANSPORT
 * panel, including their positions, theme styling, pointer mode, and layout
 * metadata. The main sketch wires the callbacks and treats this as one module.
 */
class PlayerControl {
    /**
     * Creates transport controls and optionally wires them to the DATA FEED.
     * @param {Player} playerObj - Playback controller.
     * @param {string} parentId - DOM parent for p5 image buttons.
     * @param {Object} positions - Optional persisted button positions.
     * @param {TelemetryLog|null} telemetry - Shared telemetry log, if enabled.
     */
    constructor(playerObj, parentId, positions = {}, telemetry = null) {
        this.playerObj = playerObj;
        this.parentId = parentId;
        this.telemetry = telemetry;
        this.buttonSize = 22;

        // Button keys are persisted in the layout, so keep them stable.
        this.buttons = [
            this.createButtonConfig("prevButton", "assets/prev.png", "Previous", () => this.runTransportAction("Previous track requested", () => this.playerObj.playPrevious()), positions.prevButton || { x: 132, y: 62 }),
            this.createButtonConfig("playButton", "assets/play.png", "Play", () => this.runTransportAction("State :: playing", () => this.playerObj.playSong()), positions.playButton || { x: 158, y: 62 }),
            this.createButtonConfig("pauseButton", "assets/pause.png", "Pause", () => this.runTransportAction("State :: paused", () => this.playerObj.pauseSong()), positions.pauseButton || { x: 184, y: 62 }),
            this.createButtonConfig("stopButton", "assets/stop.png", "Stop", () => this.runTransportAction("State :: stopped", () => this.playerObj.stopSong()), positions.stopButton || { x: 210, y: 62 }),
            this.createButtonConfig("nextButton", "assets/next.png", "Next", () => this.runTransportAction("Next track requested", () => this.playerObj.playNext()), positions.nextButton || { x: 236, y: 62 })
        ];

        this.createDomButtons();
    }

    /**
     * Emits the transport event before running the actual playback command.
     * The action remains delegated to Player so this class only owns controls.
     */
    runTransportAction(message, action) {
        if (this.telemetry) {
            this.telemetry.emit("TRANSPORT", message, {
                key: `transport-${message}`,
                throttleMs: 300,
                dedupe: false
            });
        }
        action();
    }

    createButtonConfig(key, asset, label, onPress, position) {
        return {
            key,
            asset,
            label,
            onPress,
            x: position.x,
            y: position.y,
            w: this.buttonSize,
            h: this.buttonSize,
            element: null
        };
    }

    createDomButtons() {
        for (const button of this.buttons) {
            // Transport controls are DOM image elements rather than canvas
            // shapes, so they can receive direct mousePressed callbacks.
            button.element = createImg(button.asset, button.label);
            button.element.parent(this.parentId);
            button.element.mousePressed(button.onPress);
            this.styleButton(button.element);
        }
    }

    applyTheme() {
        for (const button of this.buttons) {
            if (button.element) {
                this.styleButton(button.element);
            }
        }
    }

    styleButton(element) {
        // Dark themes need a tuned icon filter so the black PNGs keep a neon
        // edge while still reading clearly against the panel background.
        const iconFilter = UI.transportIconFilter || "";
        const glowAlpha = currentThemeName === "stellar" ? 0.16 : 0.28;
        const iconGlowAlpha = currentThemeName === "stellar" ? 0.35 : 0.85;

        element.style("width", `${this.buttonSize}px`);
        element.style("height", `${this.buttonSize}px`);
        element.style("padding", "3px");
        element.style("border", `1px solid ${rgbaString(UI.line, 0.48)}`);
        element.style("border-radius", "4px");
        element.style("background", rgbaString(UI.panel, 0.92));
        element.style("box-shadow", currentThemeName === "stellar"
            ? `0 0 14px ${rgbaString(UI.line, glowAlpha)}`
            : `0 0 14px ${rgbaString(UI.line, glowAlpha)}, inset 0 0 10px ${rgbaString(UI.line, 0.12)}`);
        element.style("filter", iconFilter
            ? `${iconFilter} drop-shadow(0 0 5px ${rgbaString(UI.line, iconGlowAlpha)})`
            : `drop-shadow(0 0 4px ${rgbaString(UI.line, iconGlowAlpha)})`);
        element.style("cursor", "pointer");
    }

    draw() {
        for (const button of this.buttons) {
            if (button.element) {
                button.element.position(button.x, button.y);
            }
        }
    }

    setPointerMode(pointerMode) {
        for (const button of this.buttons) {
            if (button.element) {
                button.element.style("pointer-events", pointerMode);
            }
        }
    }

    getLayoutItems() {
        // Return plain layout snapshots. The layout manager mutates positions
        // through moveButtonTo(), not by editing the internal button objects.
        return this.buttons.map((button) => ({
            key: button.key,
            x: button.x,
            y: button.y,
            w: button.w,
            h: button.h
        }));
    }

    moveButtonTo(key, x, y) {
        const button = this.buttons.find((candidate) => candidate.key === key);
        if (!button) {
            return;
        }

        button.x = x;
        button.y = y;
    }

    fitToPanel(panel) {
        // Center the full transport group in the panel body. The panel owns
        // placement; individual buttons still remain separately movable when
        // Move Elements is enabled.
        const gap = 4;
        const totalWidth = this.buttons.reduce((sum, button) => sum + button.w, 0) + gap * (this.buttons.length - 1);
        let x = Math.round(panel.x + (panel.w - totalWidth) / 2);
        const y = panel.y + 35;

        for (const button of this.buttons) {
            button.x = x;
            button.y = y;
            x += button.w + gap;
        }
    }
}

/* ---- lib/userappcontrol.js ---- */
/**
 * Application-level controls for the USER CONTROL panel.
 *
 * UserAppControl owns the theme, fullscreen, and logout buttons. The sketch
 * passes in callbacks for app-specific actions so this module can manage
 * drawing, hit-testing, layout metadata, and fullscreen listener state without
 * knowing how configuration storage or canvas resizing are implemented.
 */
class UserAppControl {
    constructor(callbacks = {}, positions = {}) {
        this.callbacks = callbacks;
        this.fullscreenListenerAttached = false;

        // Button keys are persisted in saved layouts. Keep these stable.
        this.buttons = [
            this.createButtonConfig("themeButton", "CYBER", positions.themeButton || { x: 34, y: 141, w: 66, h: 22 }),
            this.createButtonConfig("fullscreenButton", "FULL", positions.fullscreenButton || { x: 34, y: 167, w: 66, h: 22 }),
            this.createButtonConfig("logoutButton", "LOGOUT", positions.logoutButton || { x: 33, y: 208, w: 66, h: 22 })
        ];
    }

    createButtonConfig(key, label, bounds) {
        return {
            key,
            label,
            x: bounds.x,
            y: bounds.y,
            w: bounds.w,
            h: bounds.h
        };
    }

    attachFullscreenResizeListener() {
        if (this.fullscreenListenerAttached) {
            return;
        }

        document.addEventListener("fullscreenchange", () => {
            if (this.callbacks.onFullscreenChanged) {
                this.callbacks.onFullscreenChanged();
            }
        });
        this.fullscreenListenerAttached = true;
    }

    draw() {
        this.setButtonLabel("themeButton", currentThemeName.toUpperCase());
        this.setButtonLabel("fullscreenButton", this.isFullscreenActive() ? "WINDOW" : "FULL");

        for (const button of this.buttons) {
            this.drawButton(button, this.contains(button, mouseX, mouseY));
        }
    }

    drawButton(button, hover) {
        push();
        stroke(hover ? color(UI.pink[0], UI.pink[1], UI.pink[2]) : color(UI.amber[0], UI.amber[1], UI.amber[2], 170));
        strokeWeight(1);
        fill(hover ? color(UI.pink[0], UI.pink[1], UI.pink[2], 44) : color(UI.panelAlt[0], UI.panelAlt[1], UI.panelAlt[2], 230));
        rect(button.x, button.y, button.w, button.h, 4);

        noStroke();
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(10);
        textAlign(CENTER, CENTER);
        text(button.label, button.x + button.w / 2, button.y + button.h / 2);
        pop();
    }

    handleMouse(mx, my) {
        if (this.handleButton(mx, my, "themeButton", () => this.callbacks.onTheme && this.callbacks.onTheme())) {
            return true;
        }
        if (this.handleButton(mx, my, "fullscreenButton", () => this.toggleFullscreen())) {
            return true;
        }
        if (this.handleButton(mx, my, "logoutButton", () => this.callbacks.onLogout && this.callbacks.onLogout())) {
            return true;
        }

        return false;
    }

    handleButton(mx, my, key, action) {
        const button = this.getButton(key);
        if (!button || !this.contains(button, mx, my)) {
            return false;
        }

        action();
        return true;
    }

    async toggleFullscreen() {
        try {
            if (this.isFullscreenActive()) {
                await document.exitFullscreen();
            } else {
                await document.documentElement.requestFullscreen();
            }
            if (this.callbacks.onFullscreenChanged) {
                setTimeout(this.callbacks.onFullscreenChanged, 80);
            }
        } catch (error) {
            console.error("Fullscreen toggle failed:", error);
        }
    }

    isFullscreenActive() {
        return !!document.fullscreenElement;
    }

    getLayoutItems() {
        // Return plain snapshots so the layout manager cannot mutate internal
        // button objects directly. Movement goes through moveButtonTo().
        return this.buttons.map((button) => ({
            key: button.key,
            x: button.x,
            y: button.y,
            w: button.w,
            h: button.h
        }));
    }

    moveButtonTo(key, x, y) {
        const button = this.getButton(key);
        if (!button) {
            return;
        }

        button.x = x;
        button.y = y;
    }

    fitToPanel(panel, options = { theme: true, fullscreen: true, logout: true }) {
        const logoutButton = this.getButton("logoutButton");
        if (!panel || !logoutButton) {
            return;
        }

        // Stack app buttons near the bottom of USER CONTROL, centered in the
        // panel. Existing saved layouts can opt out per button.
        const buttonX = panel.x + Math.max(10, Math.round((panel.w - logoutButton.w) / 2));
        if (options.theme) {
            this.moveButtonTo("themeButton", buttonX, panel.y + panel.h - 96);
        }
        if (options.fullscreen) {
            this.moveButtonTo("fullscreenButton", buttonX, panel.y + panel.h - 66);
        }
        if (options.logout) {
            this.moveButtonTo("logoutButton", buttonX, panel.y + panel.h - 36);
        }
    }

    setButtonLabel(key, label) {
        const button = this.getButton(key);
        if (button) {
            button.label = label;
        }
    }

    getButton(key) {
        return this.buttons.find((button) => button.key === key);
    }

    contains(button, mx, my) {
        return mx >= button.x && mx <= button.x + button.w && my >= button.y && my <= button.y + button.h;
    }
}

/* ---- lib/sketch.js ---- */
/**
 * @fileOverview
 * This file contains the main sketch for Subsonic Neon Deck using p5.js.
 * It includes the setup, preload, and draw functions,
 * as well as various helper functions for audio playback, UI elements, and API interactions.
 * @Leo
 */

var SUBSONIC_CONFIG_KEY = 'subsonicPlayerConfig';
var QUEUE_STATE_VERSION = 1;
var QUEUE_SAVE_DEBOUNCE_MS = 300;

// Global startup state. The app does not draw the full deck until credentials
// are validated and all server-dependent components are created.
var SubsonicObj;
var appReady = false;
var appStatusMessage = "Starting...";

// Panel-bound visualizers. Their internal sizing/positioning rules live in
// each module; sketch.js only instantiates, draws, and syncs them with panels.
var spectrum;
var waveform;
var vuMeters;
var vectorScope;
var keepPlaying=false; //semaphore

var song = null; // p5.SoundFile object for playback
var SongsListObj; //local playlist object


var vol;
var pan;
var rate;

var playerControl;
var userAppControl;

var playListSelect;
var songSelect;

var progressBar;
var telemetryLog;
var telemetryPanel;
var lastTelemetrySampleAt = 0;
var lastAudioTelemetrySnapshot = null;

var playingInfo;

var audioEffects;

var filtersON = false; //filters start off for lower default CPU/audio load

var filtersOnOffSwitch; //switch for filters on/off
var loopOnOffSwitch; //switch for loop on/off
var randomPlaySwitch; //switch for random play mode
var skinnyModeSwitch; // ##SKINNY MODE: switch for low-power skinny mode
var movePanelsSwitch; //switch for enabling panel movement/resizing
var moveElementsSwitch; //switch for enabling individual element movement
// TODO: Lyrics feature is parked until the external lyrics API is available again.
// var lyricsVisibleSwitch; //switch for showing and hiding the lyrics column
var volSlider;
var balanceSlider;
var rateSlider;
var bassSlider;
var midSlider;
var trebleSlider;
var reverbSlider;
var reverbVolSlider;
var lastPlayingInfoSongId = null;

var panelLayoutEditMode = false;
var layoutManager;
var lastDomPointerMode = null;
var queueSaveTimer = null;
var pendingQueueState = null;
var isRestoringQueueState = false;

// Remaining DOM controls created with p5. Transport and user app controls live
// in their own modules; these select positions are still coordinated here.
var playlistSelectPosition = { x: 33, y: 325, w: 200, h: 25 };
var songSelectPosition = { x: 34, y: 370, w: 200, h: 25 };
var playlistLabelPosition = { x: 30, y: 308, w: 80, h: 12 };
var songLabelPosition = { x: 32, y: 357, w: 80, h: 12 };
// TODO: Lyrics feature is parked until the external lyrics API is available again.
// var lyricsVisible = false;
var currentCanvasWidth = 1;
var currentCanvasHeight = 1;

/**
 * File browser instance
 * @type {FileBrowser}
 * @param {number} x - The x position of the file browser.
 * @param {number} y - The y position of the file browser.
 * @param {number} w - The width of the file browser.
 * @param {number} h - The height of the file browser.
 * @returns {void}
 * @description
 * Class that creates a file browser using the Subsonic API getIndexes() and getMusicDirectory()
 * and displays it in a scrollable list.
 *
 */
var FileBrowserObj;



/**
 * Player instance
 * @type {Player}
*/
var PlayerObj;



/**
 * Preloads assets before the sketch starts.
 * Loads a dummy audio file to enable isPaused() or isPlaying() functionality.
 *
 * @function
 * @global
 */
function preload()
{
//dummy audio so that isPaused() or isPlaying() are enabled
song = loadSound('assets/dot.mp3');
song.setVolume(0.5); //set default volume

}

window.addEventListener("beforeunload", () => {
    flushQueueStateSave();
});

// ---------------------------------------------------------------------------
// Subsonic Persistence And Authentication
// ---------------------------------------------------------------------------

/**
 * Returns the saved Subsonic credentials if the required auth fields exist.
 * This is stricter than getStoredAppState() because startup should only reuse
 * a config that can actually authenticate against the server.
 */
function getStoredSubsonicConfig() {
    const config = getStoredAppState();
    if (!config || !config.server || !config.user || !config.token || !config.salt) {
        return null;
    }

    return config;
}

/**
 * Reads the full application state object from localStorage.
 * Non-auth preferences such as theme, layout, and skinny mode live here too.
 */
function getStoredAppState() {
    try {
        const rawConfig = localStorage.getItem(SUBSONIC_CONFIG_KEY);
        if (!rawConfig) {
            return null;
        }

        return JSON.parse(rawConfig);
    } catch (error) {
        console.error("Unable to load saved Subsonic configuration:", error);
        return null;
    }
}

/**
 * Merges partial state into localStorage without dropping unrelated settings.
 * Use this for durable app preferences, not for transient runtime flags.
 */
function saveSubsonicConfig(config) {
    localStorage.setItem(SUBSONIC_CONFIG_KEY, JSON.stringify({
        ...(getStoredAppState() || {}),
        ...config
    }));
}

/**
 * Updates stored state only when a valid authenticated config already exists.
 * This prevents UI preferences from creating a partial login record.
 */
function updateStoredSubsonicConfig(updates) {
    const config = getStoredSubsonicConfig();
    if (!config) {
        return;
    }

    saveSubsonicConfig({
        ...config,
        ...updates
    });
}

/**
 * Receives compact queue snapshots from PlayList and schedules persistence.
 * Debouncing keeps folder-add batches from writing localStorage repeatedly.
 * @param {Object} state - Compact queue state from PlayList.getPersistedState().
 */
function queueStateChanged(state) {
    if (isRestoringQueueState) {
        return;
    }

    scheduleQueueStateSave(state);
}

/**
 * Schedules queue state persistence with a short debounce.
 * @param {Object} state - Compact queue state.
 */
function scheduleQueueStateSave(state) {
    pendingQueueState = state;
    if (queueSaveTimer) {
        clearTimeout(queueSaveTimer);
    }

    queueSaveTimer = setTimeout(() => {
        flushQueueStateSave();
    }, QUEUE_SAVE_DEBOUNCE_MS);
}

/**
 * Writes any pending queue snapshot immediately.
 * This is used before page unload so a quick refresh after queue edits does not
 * lose the last debounced state.
 */
function flushQueueStateSave() {
    if (queueSaveTimer) {
        clearTimeout(queueSaveTimer);
        queueSaveTimer = null;
    }

    if (!pendingQueueState) {
        return;
    }

    const state = pendingQueueState;
    pendingQueueState = null;
    saveQueueState(state);
}

/**
 * Stores the current queue snapshot in the authenticated app config.
 * The server/user guard prevents restoring a queue after switching accounts
 * or Subsonic nodes.
 * @param {Object} state - Compact queue state.
 */
function saveQueueState(state) {
    const config = getStoredSubsonicConfig();
    if (!config) {
        return;
    }

    const tracks = Array.isArray(state?.tracks) ? state.tracks : [];
    const queueState = {
        version: QUEUE_STATE_VERSION,
        savedAt: new Date().toISOString(),
        server: config.server,
        user: config.user,
        pointer: Number.isInteger(state?.pointer) ? state.pointer : 0,
        tracks: tracks
    };

    try {
        updateStoredSubsonicConfig({ queueState: queueState });
    } catch (error) {
        console.warn("Unable to persist queue state:", error);
        if (telemetryLog) {
            telemetryLog.emit("QUEUE", "Queue persistence failed", { level: "warn", throttleMs: 10000 });
        }
    }
}

/**
 * Restores a saved queue for the current Subsonic account without autoplay.
 * Playback only starts after an explicit user action, matching browser audio
 * policies and avoiding surprises on page refresh.
 * @param {Object|null} queueState - Saved queue state from localStorage.
 */
function restoreQueueState(queueState) {
    if (!queueState || !SongsListObj || !SubsonicObj) {
        return;
    }

    if (!isQueueStateForCurrentAccount(queueState)) {
        return;
    }

    isRestoringQueueState = true;
    const restored = SongsListObj.restorePersistedState(queueState);
    isRestoringQueueState = false;

    if (restored && telemetryLog) {
        telemetryLog.emit("QUEUE", `Restored queue :: ${SongsListObj.getLength()} tracks`);
    }
}

/**
 * Verifies that a saved queue belongs to the currently authenticated account.
 * @param {Object} queueState - Saved queue state.
 * @returns {boolean} True when the queue can be restored.
 */
function isQueueStateForCurrentAccount(queueState) {
    const config = getStoredSubsonicConfig();
    return !!config &&
        queueState.version === QUEUE_STATE_VERSION &&
        queueState.server === config.server &&
        queueState.user === config.user &&
        Array.isArray(queueState.tracks);
}

/**
 * Clears login credentials and saved panel layout, then leaves visual
 * preferences such as theme intact for the next sign-in.
 */
function clearSubsonicAuth() {
    if (queueSaveTimer) {
        clearTimeout(queueSaveTimer);
        queueSaveTimer = null;
    }
    pendingQueueState = null;

    const config = getStoredAppState() || {};
    delete config.server;
    delete config.user;
    delete config.token;
    delete config.salt;
    // Logout should also reset the editable deck arrangement. Theme and other
    // non-layout preferences are kept so the app still feels familiar after
    // logging back in.
    delete config.layout;
    delete config.layoutOwners;
    delete config.queueState;
    localStorage.setItem(SUBSONIC_CONFIG_KEY, JSON.stringify(config));
}

/**
 * Re-applies the active theme to DOM-based controls and slider accents.
 * Canvas components read UI directly while drawing, but DOM controls need
 * explicit style updates when the theme changes.
 */
function updateComponentThemeColors() {
    if (playListSelect) styleSelect(playListSelect);
    if (songSelect) styleSelect(songSelect);
    if (playerControl) playerControl.applyTheme();

    const sliderPairs = [
        [volSlider, "line"],
        [balanceSlider, "pink"],
        [rateSlider, "amber"],
        [bassSlider, "line"],
        [midSlider, "pink"],
        [trebleSlider, "amber"],
        [reverbSlider, "line"],
        [reverbVolSlider, "pink"]
    ];
    for (const [slider, accent] of sliderPairs) {
        if (slider) {
            slider.color1 = cssHex(UI.field);
            slider.color2 = cssHex(UI[accent]);
        }
    }
}

Theme.onChange(updateComponentThemeColors);

/**
 * Validates tokenized credentials with a Subsonic ping before building the
 * deck. Rejected credentials keep the user on the setup form.
 */
async function isSubsonicConfigAccepted(config) {
    if (!config || !config.server || !config.user || !config.token || !config.salt) {
        return false;
    }

    const client = new SubsonicClient(config.server, config.user, config.token, config.salt);
    const ping = await client.request("ping");
    return !!ping;
}

/**
 * Calculates the canvas size from the visible viewport.
 * The deck intentionally avoids page scroll so touch drags move deck elements
 * rather than the browser page.
 */
function getCanvasSize() {
    const pagePadding = 44;
    const shellBorder = 2;
    // TODO: Lyrics feature is parked until the external lyrics API is available again.
    // const layoutGap = lyricsVisible ? 24 : 0;
    // const lyricsWidth = lyricsVisible ? 500 : 0;
    const availableWidth = window.innerWidth - pagePadding - shellBorder;
    const availableHeight = window.innerHeight - pagePadding - shellBorder;

    return {
        width: Math.max(1, Math.floor(availableWidth)),
        height: Math.max(1, Math.floor(availableHeight))
    };
}

/**
 * Resizes the p5 canvas and its shell element to the current viewport.
 * The shell reserves space for its border and clips overflow on small screens.
 */
function resizeCanvasToAvailableSpace() {
    const size = getCanvasSize();
    currentCanvasWidth = size.width;
    currentCanvasHeight = size.height;

    if (typeof resizeCanvas === "function" && typeof width !== "undefined" && typeof height !== "undefined" && width && height) {
        resizeCanvas(currentCanvasWidth, currentCanvasHeight);
    }

    const canvasContainer = document.getElementById("cnv");
    if (canvasContainer) {
        // The shell has a 1px border on each side and uses border-box sizing.
        // Keep the canvas as the content size, then add border space to the shell.
        canvasContainer.style.width = (currentCanvasWidth + 2) + "px";
        canvasContainer.style.height = (currentCanvasHeight + 2) + "px";
        canvasContainer.style.overflow = "hidden";
    }

    // TODO: Lyrics feature is parked until the external lyrics API is available again.
    // const lyricsPanel = document.getElementById("otro");
    // if (lyricsPanel) {
    //     lyricsPanel.style.display = lyricsVisible ? "block" : "none";
    //     lyricsPanel.style.minHeight = currentCanvasHeight + "px";
    // }
}

