/**
 * Applies or rebuilds audio routing for the current song and filter state.
 */
function configureAudioRouting(force=false){
    const filtersState = filtersOnOffSwitch ? filtersOnOffSwitch.getState() : filtersON;
    audioEffects.configure(song, filtersState, force, getAudioControlValues());
}

/**
 * Handles Player's periodic maintenance event between tracks.
 * PERF PATCH [audio-runtime-periodic-maintenance]: Player owns transport
 * timing, while sketch.js owns app-level audio helpers. This callback logs the
 * cycle in DATA FEED and recycles app-owned nodes that can otherwise keep
 * Firefox GraphRunner busy during day-long sessions.
 * @param {Object} event - Maintenance metadata emitted by Player.
 */
function handlePlayerMaintenance(event = {}) {
    recycleAudioRuntime();

    if (telemetryLog) {
        const count = event.completedCount ?? "?";
        const delay = event.delayMs ?? 0;
        telemetryLog.emit("SYSTEM", `Audio maintenance :: cycle ${count}, runtime recycled (${delay}ms gap)`);
    }
}

/**
 * Recycles app-owned audio graph helpers during a maintenance gap.
 * PERF PATCH [audio-runtime-periodic-maintenance]: the active SoundFile has
 * already been detached by Player, so this is the safe point to drop FX routes
 * and replace visualizer worklets before the next stream is loaded.
 */
function recycleAudioRuntime() {
    if (audioEffects) {
        audioEffects.clearRouting();
    }

    audioEffects = new AudioEffects();
    recycleVisualizerAudioNodes(vuMeters);
}

/**
 * Calls a visualizer's audio-node recycle hook when it supports one.
 * PERF PATCH [audio-runtime-periodic-maintenance]: keeps the maintenance
 * callback extensible for Spectrum/Waveform/VectorScope if future profiles
 * show their analyzer nodes accumulating CPU.
 * @param {Object|null} visualizer - Panel component that may own audio nodes.
 */
function recycleVisualizerAudioNodes(visualizer) {
    if (!visualizer || typeof visualizer.recycleAudioNodes !== "function") {
        return;
    }

    visualizer.recycleAudioNodes();
}


/**
 * Draws static text labels for DOM select controls that sit on the canvas.
 */
function printLabels(){

    push();
    fill(UI.muted[0], UI.muted[1], UI.muted[2]);
    noStroke();
    textSize(10);
    textAlign(LEFT, TOP);
    text('Playlist', playlistLabelPosition.x, playlistLabelPosition.y);
    text('Songs', songLabelPosition.x, songLabelPosition.y);
    pop();
}


