/* ---- lib/playlist.js ---- */
class PlayList{

    /**
     * Creates a new PlayList instance
     * (not using the word playlist to avoid confusion with Subsonic's playlist)
     * @param {Array} songslist - An array of song objects to initialize the playlist
     */
    constructor(x,y,w,h){ // Initialize with an empty array if no songs are provided
        this.songslist = []; // Store the list of songs
        this.pointer = 0;
        this.randomPlayEnabled = false;
        this.randomPending = [];
        this.randomHistory = [];
        // PERF PATCH [bounded-random-history]: previous-track support must not
        // turn random playback into unbounded history in all-day sessions.
        this.maxRandomHistory = 500;

        this.x=x;
        this.y=y;
        this.w=w;
        this.h=h;

        this.scrollOffset = 0; // Scroll offset for the list
        this.itemHeight = 20; // Height of each item
        this.scrollbarWidth = 20; // Width of the scrollbar
        this.scrollbarDragging = false; // Is the scrollbar being dragged
        this.scrollbarY = 0; // Y position of the scrollbar
        this.scrollbarHeight = 0; // Height of the scrollbar
        this.scrollbarDragOffset = 0; // Offset when dragging the scrollbar
        this.scrollbarColor = null; // Scrollbar drawing reads the active theme from UI.line.
        this.toolbarWidth = 28; // Width of the vertical queue toolbar
        this.telemetry = null; // Optional DATA FEED logger for queue actions
        this.onChanged = null; // Optional callback used by sketch.js to persist queue snapshots.
        this.changeEventsSuspended = false; // Prevents restore batches from saving half-built queues.
        this.removeMode = false; // When enabled, row clicks remove queue items.
        this.toolbarButtons = [
            {
                icon: "X", // Clear queue
                action: () => this.clearWithTelemetry(),
                height: 20
            },
            {
                icon: "-", // Remove mode toggle
                action: () => this.toggleRemoveMode(),
                active: () => this.removeMode,
                height: 20
            }
        ];
    }

    /**
     * Wires an optional DATA FEED logger after startup objects exist.
     * @param {TelemetryLog|null} telemetry - Shared telemetry log.
     */
    setTelemetry(telemetry) {
        this.telemetry = telemetry;
    }

    /**
     * Registers a callback that runs whenever queue content or pointer changes.
     * The playlist stays storage-agnostic; callers decide whether to persist,
     * export, or ignore the emitted compact state.
     * @param {Function|null} callback - Receives getPersistedState() snapshots.
     */
    setOnChanged(callback) {
        this.onChanged = typeof callback === "function" ? callback : null;
    }

    /**
     * Emits a compact queue snapshot to the registered change callback.
     * This keeps persistence centralized in sketch.js while PlayList remains
     * responsible for knowing when its queue state has changed.
     */
    emitChanged() {
        if (this.changeEventsSuspended || !this.onChanged) {
            return;
        }

        this.onChanged(this.getPersistedState());
    }

    /**
     * Moves the pointer to the next song in the playlist
     */
    next(loop = true){
        if (this.songslist.length === 0) {
            return false;
        }

        if (this.randomPlayEnabled) {
            return this.nextRandom(loop);
        }

        if (this.pointer==this.songslist.length-1){
            if (!loop) {
                return false;
            }
            this.pointer=0;
        }else{
            this.pointer+=1;
        }

        return true;
    }

    /**
     * Moves the pointer to the previous song in the playlist
     */
    previous(loop = true){
        if (this.songslist.length === 0) {
            return false;
        }

        if (this.randomPlayEnabled && this.randomHistory.length > 0) {
            this.pointer = this.randomHistory.pop();
            this.rebuildRandomPending();
            return true;
        }

        if (this.pointer==0){
            if (!loop) {
                return false;
            }
            this.pointer=this.songslist.length-1
        }else{
            this.pointer-=1;
        }

        return true;
    }

    /**
     * Returns the current song in the playlist
     * @returns {Object} The current song object
     */
    getCurrent(){
        return this.songslist[this.pointer];
    }

    /**
     * Returns the next song in the playlist
     * @returns {Object} The next song object
     */
    getNext(){
        this.next();
        return this.getCurrent();
    }

    /**
     * Returns the length of the playlist
     * @returns {number} The length of the playlist
     */
    getLength(){
        return this.songslist.length;
    }

    /**
     * Returns a song from the playlist by index
     * @param {number} index - The index of the song to retrieve
     * @returns {Object|null} The song object or null if index is out of bounds
     */
    getSong(index){
        if(index>=0 && index<=this.songslist.length-1){
            return this.songslist[index];
        }else{
            console.log("Playlist: Index sent out of bounds");
            return null;
        }
    }

    /**
     * Clears the playlist
     */
    clear(){
        this.songslist.splice(0,this.songslist.length);//remove all elements
        this.songslist=[]; //make sure the array is empty
        this.pointer=0;
        // Queue view reset: clearing must return the list viewport to the
        // first page so newly appended tracks are visible immediately.
        this.scrollOffset=0;
        this.scrollbarDragging=false;
        this.scrollbarY=0;
        this.scrollbarHeight=0;
        this.resetRandomPlayState();
        this.emitChanged();
    }

    /**
     * Clears the entire queue from the toolbar and emits a DATA FEED event.
     */
    clearWithTelemetry() {
        const removedCount = this.songslist.length;
        this.clear();
        if (this.telemetry) {
            this.telemetry.emit("QUEUE", `Cleared queue :: ${removedCount} tracks`);
        }
    }

    /**
     * Adds a list of songs to the playlist
     * @param {Array} songslist - The list of songs to add
     */
    addSongsList(songslist){
        this.songslist.push(...songslist); //'...' spread append
        this.rebuildRandomPending();
        this.emitChanged();
    }

    /**
     * Removes a song from the playlist by index
     * @param {number} index - The index of the song to remove
     */
    removeSong(index){
        if (index < 0 || index >= this.songslist.length) {
            return null;
        }

        const removed = this.songslist.splice(index,1)[0] || null;
        this.pointer = Math.min(this.pointer, Math.max(0, this.songslist.length - 1));
        if (index < this.pointer) {
            this.pointer = Math.max(0, this.pointer - 1);
        }
        this.resetRandomPlayState();
        this.emitRemovedSong(removed);
        this.emitChanged();
        return removed;
    }

    /**
     * Adds a song to the playlist
     * @param {Object} song - The song object to add
     */
    addSong(song){
        this.songslist.push(song);
        this.rebuildRandomPending();
        this.emitChanged();
    }

    /**
     * Emits a queue removal event to DATA FEED.
     * @param {Object|null} song - Removed song object.
     */
    emitRemovedSong(song) {
        if (!this.telemetry || !song) {
            return;
        }

        const artist = song.artist || "Unknown artist";
        const title = song.title || song.name || "Untitled";
        this.telemetry.emit("QUEUE", `Removed track :: ${artist} - ${title}`);
    }

    /**
     * Toggles remove mode for visible queue row clicks.
     * Normal mode keeps click as play-from-here; remove mode deletes the row
     * the user clicks without interrupting the active audio buffer.
     */
    toggleRemoveMode() {
        this.removeMode = !this.removeMode;
        if (this.telemetry) {
            this.telemetry.emit("QUEUE", `Remove mode :: ${this.removeMode ? "enabled" : "disabled"}`, {
                key: "queue-remove-mode",
                dedupe: true
            });
        }
    }

    /**
     * Queries the playing state
     * @returns {boolean} The playing state
     * @param {boolean} playing - The next playing state
     */
    isPlaying(playing=null){
        if (playing==null){
            return this.playing;
        }else{
            this.playing=playing;
        }

    }

    /**
     * Queries the next loaded state
     * @returns {boolean} The next loaded state
     * @param {boolean} loaded - The next loaded state
     */
    isNextLoaded(loaded=null){
        if (loaded==null){
            return this.nextloaded;
        }else{
            this.nextloaded=loaded;
        }

    }

    /**
     * Sets the pointer to a specific value
     * @param {number} val - The value to set the pointer to
     */
    setPointer(val){
        if(val>=0 && val<=this.songslist.length-1){
            this.pointer=val;
            this.markRandomIndexPlayed(val);
            this.emitChanged();
        }else{
            console.log("Playlist: Pointer sent out of bounds "+ val);
        }
    }

    /**
     * Returns the playlist
     * @returns {Array} The songs list
     */
    getPlayList(){
        return this.songslist;
    }

    /**
     * Builds a compact, storage-safe queue snapshot.
     * Audio buffers, stream URLs, and runtime-only p5.sound objects are
     * intentionally excluded so localStorage only keeps lightweight metadata.
     * @returns {Object} Persistable queue state.
     */
    getPersistedState() {
        return {
            pointer: this.songslist.length > 0 ? Math.min(this.pointer, this.songslist.length - 1) : 0,
            tracks: this.songslist
                .filter((song) => song && song.id)
                .map((song) => this.serializeSong(song))
        };
    }

    /**
     * Restores queue content from a compact persisted snapshot.
     * Change events are suspended during the batch so callers can decide when
     * the restored state should be saved again.
     * @param {Object|null} state - Persisted queue state.
     * @returns {boolean} True when a non-empty queue was restored.
     */
    restorePersistedState(state) {
        const tracks = Array.isArray(state?.tracks) ? state.tracks.filter((song) => song && song.id) : [];
        if (tracks.length === 0) {
            return false;
        }

        this.changeEventsSuspended = true;
        try {
            this.clear();
            this.addSongsList(tracks);
            const pointer = Number.isInteger(state.pointer) ? state.pointer : 0;
            this.pointer = Math.max(0, Math.min(pointer, this.songslist.length - 1));
            this.markRandomIndexPlayed(this.pointer);
        } finally {
            this.changeEventsSuspended = false;
        }
        this.emitChanged();
        return true;
    }

    /**
     * Converts one queue song into the metadata needed to redraw and replay it.
     * @param {Object} song - Song object from Subsonic or restored queue state.
     * @returns {Object} Compact song metadata.
     */
    serializeSong(song) {
        return {
            id: song.id,
            title: song.title || song.name || "Untitled",
            name: song.name || song.title || "Untitled",
            artist: song.artist || "",
            artistId: song.artistId || "",
            album: song.album || "",
            albumId: song.albumId || "",
            coverArt: song.coverArt || "",
            duration: Number.isFinite(song.duration) ? song.duration : null,
            track: Number.isFinite(song.track) ? song.track : null,
            discNumber: Number.isFinite(song.discNumber) ? song.discNumber : null,
            parent: song.parent || ""
        };
    }

    /**
     * Points to a random song in the playlist
     * @returns {void}
     */
    pointToRandom(){
        this.nextRandom();
    }

    /**
     * Enables or disables random play without reordering the visible queue.
     * Random play chooses a random next pointer from unplayed candidates.
     */
    setRandomPlay(enabled) {
        const nextEnabled = !!enabled;
        if (this.randomPlayEnabled === nextEnabled) {
            return;
        }

        this.randomPlayEnabled = nextEnabled;
        this.resetRandomPlayState();
        this.markRandomIndexPlayed(this.pointer);
        this.emitChanged();
    }

    isRandomPlayEnabled() {
        return this.randomPlayEnabled;
    }

    resetRandomPlayState() {
        this.randomPending = [];
        this.randomHistory = [];
        this.rebuildRandomPending();
    }

    rebuildRandomPending() {
        this.randomPending = [];
        for (let i = 0; i < this.songslist.length; i++) {
            if (i !== this.pointer) {
                this.randomPending.push(i);
            }
        }
    }

    markRandomIndexPlayed(index) {
        this.randomPending = this.randomPending.filter((candidate) => candidate !== index);
    }

    nextRandom(loop = true) {
        if (this.songslist.length === 0) {
            return false;
        }

        if (this.songslist.length <= 1) {
            return loop;
        }

        if (this.randomPending.length === 0) {
            if (!loop) {
                return false;
            }
            this.rebuildRandomPending();
        }

        if (this.randomPending.length === 0) {
            return false;
        }

        const previousPointer = this.pointer;
        const randomPosition = Math.floor(Math.random() * this.randomPending.length);
        this.pointer = this.randomPending.splice(randomPosition, 1)[0];
        if (previousPointer !== this.pointer) {
            this.randomHistory.push(previousPointer);
            this.trimRandomHistory();
        }

        return true;
    }

    /**
     * Trims random playback history so previous-track navigation remains useful
     * without retaining an unbounded list during long random sessions.
     */
    trimRandomHistory() {
        // PERF PATCH [bounded-random-history]: keep enough history for UX, but
        // cap it by both queue size and a fixed ceiling.
        const maxHistory = Math.max(1, Math.min(this.maxRandomHistory, this.songslist.length));
        if (this.randomHistory.length > maxHistory) {
            this.randomHistory.splice(0, this.randomHistory.length - maxHistory);
        }
    }



    /**
     * Returns the pointer from a songId
     * @param {ret} songId
     * @returns
     */
    getPointerFromSongId(songId){
        for (let i=0;i<this.songslist.length;i++){
            if (this.songslist[i].id==songId){
                return i;
            }
        }
        console.log("Playlist: SongId not found in playlist");
        return -1;
    }

    /**
     * Returns the pointer
     * @returns
     */
    getPointer(){
        return this.pointer;
    }


    // Draw the playlist with a scrollbar
    draw() {
        push();
        // Draw the queue toolbar
        noStroke();
        fill(UI.panelAlt[0], UI.panelAlt[1], UI.panelAlt[2]);
        rect(this.x, this.y, this.toolbarWidth, this.h, 4);

        let buttonY = this.y + 5;
        for (const button of this.toolbarButtons) {
            const active = typeof button.active === "function" && button.active();
            const buttonColor = active ? UI.line : UI.amber;
            fill(buttonColor[0], buttonColor[1], buttonColor[2], active ? 80 : 45);
            stroke(buttonColor[0], buttonColor[1], buttonColor[2]);
            rect(this.x + 5, buttonY, this.toolbarWidth - 10, button.height, 3);
            noStroke();
            fill(UI.text[0], UI.text[1], UI.text[2]);
            textSize(17);
            textAlign(CENTER, CENTER);
            text(button.icon, this.x + this.toolbarWidth / 2, buttonY + button.height / 2);
            buttonY += button.height + 5;
        }

        const listX = this.x + this.toolbarWidth;
        const listW = this.w - this.toolbarWidth;
        stroke(UI.line[0], UI.line[1], UI.line[2], 70);
        line(listX, this.y, listX, this.y + this.h);

        // Draw the background of the playlist
        noStroke();
        fill(UI.surface[0], UI.surface[1], UI.surface[2], 238);
        rect(listX, this.y, listW, this.h, 4);

        // Calculate visible items
        let visibleItems = Math.floor(this.h / this.itemHeight);
        this.clampScrollOffset(visibleItems);
        let startIndex = Math.max(0, this.scrollOffset);
        let endIndex = Math.min(this.songslist.length, startIndex + visibleItems);

        // Draw the songs in the playlist
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(12);
        textAlign(LEFT, TOP);

        for (let i = startIndex; i < endIndex; i++) {
            let yPosition = this.y + (i - startIndex) * this.itemHeight;
            if (i === this.pointer) {
                fill(UI.pink[0], UI.pink[1], UI.pink[2], 36);
                rect(listX, yPosition, listW - this.scrollbarWidth, this.itemHeight);
                fill(UI.text[0], UI.text[1], UI.text[2]);
            } else {
                fill(UI.muted[0], UI.muted[1], UI.muted[2]);
            }

            // Truncate text if it exceeds the width of the box
            let textToDisplay = this.songslist[i]?.title || "Untitled";
            let trimmed = false;
            const maxTextWidth = listW - this.scrollbarWidth - 15; // Account for padding and scrollbar
            while (textWidth(textToDisplay) > maxTextWidth) {
                textToDisplay = textToDisplay.slice(0, -1); // Remove the last character
                trimmed = true;
            }

            if (trimmed) textToDisplay = textToDisplay.trim() + "..."; // Add ellipsis

            // Draw the item name aligned to the left
            text(textToDisplay, listX + 5, yPosition + 5);
        }

        // Draw the scrollbar
        if (this.songslist.length > visibleItems) {
            // Calculate the scrollbar height and position
            this.scrollbarHeight = Math.max((visibleItems / this.songslist.length) * this.h, 20); // Minimum height
            this.scrollbarY = this.y + (this.scrollOffset / (this.songslist.length - visibleItems)) * (this.h - this.scrollbarHeight);

            // Ensure the scrollbar stays within bounds
            this.scrollbarY = Math.max(this.y, Math.min(this.scrollbarY, this.y + this.h - this.scrollbarHeight));

            fill(UI.line[0], UI.line[1], UI.line[2]);
            rect(this.x + this.w - this.scrollbarWidth + 6, this.scrollbarY, 8, this.scrollbarHeight, 4);
        }

        // Draw separator scrollbar separator
        stroke(UI.line[0], UI.line[1], UI.line[2], 70);
        line(this.x + this.w - this.scrollbarWidth, this.y, this.x + this.w - this.scrollbarWidth, this.y + this.h);

        pop();
    }

    /**
     * Keeps the queue viewport inside the legal row range after data changes.
     * This prevents stale scroll positions from pointing below the end of the
     * list after clearing or removing many queued tracks.
     * @param {number} visibleItems - Number of rows currently visible.
     */
    clampScrollOffset(visibleItems) {
        const maxOffset = Math.max(0, this.songslist.length - visibleItems);
        this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, maxOffset));
    }

    /**
     * Fits the queue list inside its owning panel body.
     * The panel header remains clear for title text and resize affordances.
     * @param {Object} panel - Layout panel bounds.
     */
    fitToPanel(panel) {
        this.x = panel.x + 12;
        this.y = panel.y + 30;
        this.w = Math.max(150, panel.w - 24);
        this.h = Math.max(70, panel.h - 42);
        this.clampScrollOffset(Math.floor(this.h / this.itemHeight));
    }

    /**
     * Minimum queue panel size used by LayoutManager resize handles.
     * @returns {Object} Minimum width and height.
     */
    getMinPanelSize() {
        return { w: 190, h: 125 };
    }

    /**
     * Tests whether the pointer is inside the playlist list area.
     * @param {number} mx - Pointer x coordinate.
     * @param {number} my - Pointer y coordinate.
     * @returns {boolean} True when the pointer is inside the playlist box.
     */
    contains(mx, my) {
        return mx >= this.x && mx <= this.x + this.w && my >= this.y && my <= this.y + this.h;
    }

    /**
     * Handles mouse wheel scrolling over the playlist.
     * @param {number} delta - Mouse wheel delta from p5's wheel event.
     */
    handleMouseWheel(delta) {
        let visibleItems = Math.floor(this.h / this.itemHeight);
        if (this.songslist.length > visibleItems) {
            // Update the scroll offset based on the wheel delta
            this.scrollOffset += delta > 0 ? 1 : -1;
            this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, this.songslist.length - visibleItems));
        }
    }

    // Handle mouse pressed events for the scrollbar
    handleMouse(mx, my) {
        let buttonY = this.y + 5;
        for (const button of this.toolbarButtons) {
            if (
                mx > this.x + 5 &&
                mx < this.x + this.toolbarWidth - 5 &&
                my > buttonY &&
                my < buttonY + button.height
            ) {
                button.action();
                return true;
            }
            buttonY += button.height + 5;
        }

        // Check if the mouse is within the bounds of the scrollbar
        if (
            mx >= this.x + this.w - this.scrollbarWidth && // Within the scrollbar's X bounds
            mx <= this.x + this.w &&
            my >= this.scrollbarY && // Within the scrollbar's Y bounds
            my <= this.scrollbarY + this.scrollbarHeight
        ) {
            this.scrollbarDragging = true; // Start dragging
            this.scrollbarDragOffset = my - this.scrollbarY; // Calculate drag offset
            return true;
        }

        return false;
    }

    getItemIndexAt(mx, my) {
        const visibleItems = Math.floor(this.h / this.itemHeight);
        const listX = this.x + this.toolbarWidth;
        const insideList = mx >= listX &&
            mx <= this.x + this.w - this.scrollbarWidth &&
            my >= this.y &&
            my <= this.y + this.h;

        if (!insideList) {
            return -1;
        }

        const row = Math.floor((my - this.y) / this.itemHeight);
        if (row < 0 || row >= visibleItems) {
            return -1;
        }

        const index = this.scrollOffset + row;
        return index >= 0 && index < this.songslist.length ? index : -1;
    }

    // Handle mouse dragged events for the scrollbar
    handleMouseDrag(mx, my) {
        if (this.scrollbarDragging) {
            let visibleItems = Math.floor(this.h / this.itemHeight);
            let maxScrollY = this.y + this.h - this.scrollbarHeight;

            // Calculate the new Y position of the scrollbar
            let newY = my - this.scrollbarDragOffset;

            // Clamp the scrollbar position to stay within bounds
            newY = Math.max(this.y, Math.min(newY, maxScrollY));
            this.scrollbarY = newY;

            // Update the scroll offset based on the scrollbar position
            this.scrollOffset = Math.round(
                ((this.scrollbarY - this.y) / (this.h - this.scrollbarHeight)) * (this.songslist.length - visibleItems)
            );

            // Ensure the scroll offset stays within bounds
            this.scrollOffset = Math.max(0, Math.min(this.scrollOffset, this.songslist.length - visibleItems));
        }
    }

    // Handle mouse released events
    handleMouseReleased() {
        this.scrollbarDragging = false;
    }

    getLayoutBounds() {
        return { x: this.x, y: this.y, w: this.w, h: this.h };
    }

    moveTo(x, y) {
        this.x = x;
        this.y = y;
    }
}

/* ---- lib/progressbar.js ---- */

/**
 * A horizontal progress bar for visualizing progress in a given range [0, 1].
 * 
 * @class
 * @param {number} x - The x-coordinate of the progress bar.
 * @param {number} y - The y-coordinate of the progress bar.
 * @param {number} width - The width of the progress bar.
 * @param {number} height - The height of the progress bar.
 * @param {number} [prefill=0] - The initial progress value (default is 0).
 */
class ProgressBarH{

    constructor(x,y,width,height,prefill=0){
        this.x=x;
        this.y=y;
        this.width=width;
        this.height=height;
        this.progress=prefill;
        this.changed=false; // Flag to indicate if the progress was changed

    }

    draw(){
        push();
        let fillx = map(this.progress,0,1,0,this.width);
        let round = 3;

        noStroke();
        fill(UI.surface[0], UI.surface[1], UI.surface[2], 210);
        rect(this.x-5, this.y-5, this.width+10, this.height+10, 6)

        fill(UI.field[0], UI.field[1], UI.field[2]);
        //background
        rect(this.x,this.y,this.width,this.height,round);
        //progress
        fill(UI.line[0], UI.line[1], UI.line[2]);
        rect(this.x,this.y,fillx,this.height,round);
        //border
        noFill();
        stroke(UI.line[0], UI.line[1], UI.line[2], 150)
        strokeWeight(1);
        rect(this.x,this.y,this.width,this.height,round);
        //pointer
        fill(UI.text[0], UI.text[1], UI.text[2])
        rectMode(CENTER);
        rect(this.x+fillx,this.y+this.height/2, 5 , this.height+5,5);

        pop();
    }

    setValue(val){
        if(val<=1.0){
            this.progress=val;
        }else{
            //console.log("Progress bar overflown!");
        }
    }

    getValue() {
        return this.progress;
    }

    isChanged() {
        return this.changed;
    }

    resetChanged() {
        this.changed = false; // Reset the changed flag
    }
 
    handleMouse(mx, my) {
        if (mx >= this.x && mx <= this.x + this.width &&
            my >= this.y && my <= this.y + this.height) {
            let newProgress = (mx - this.x) / this.width;
            this.setValue(newProgress);
            this.changed = true; // Set the changed flag to true
        }
        else {
            this.changed = false; // Reset the changed flag if outside the bar
            return;
        }
    }

    fitToPanel(panel) {
        // Keep the progress bar inside the panel body below the header. The
        // default POSITION panel is 55px tall, which maps back to the original
        // 20px bar height; taller panels make the seek target easier to grab.
        this.x = panel.x + 20;
        this.y = panel.y + 27;
        this.width = Math.max(80, panel.w - 40);
        this.height = Math.max(10, panel.h - 35);
    }

    getMinPanelSize() {
        return { w: 140, h: 45 };
    }

    getLayoutBounds() {
        return { x: this.x - 5, y: this.y - 5, w: this.width + 10, h: this.height + 10 };
    }

    moveTo(x, y) {
        this.x = x + 5;
        this.y = y + 5;
    }

}

/* ---- lib/waveform.js ---- */
/**
 * Class representing a waveform visualizer using p5.js.
 * Draws a real-time waveform as a line graph.
 * @class
 * @property {string} name - The name of the visualizer ("wavepattern").
 * @property {p5.FFT} fourier - The p5.FFT instance for waveform analysis.
 * @property {number} zoomfactor - The zoom factor for scaling the visualization.
 * @property {number} width - The width of the waveform visualization.
 * @property {number} height - The height of the waveform visualization.
 * @property {number} x - The x-coordinate of the visualization's position.
 * @property {number} y - The y-coordinate of the visualization's position.
 * @property {number} round - The border radius for the visualization background.
 * @property {number} steps - The step size for sampling waveform points (affects line smoothness and CPU usage).
 */
class WaveForm{

    constructor(x,y,width,height){
	this.name = "wavepattern";
    this.fourier = new p5.FFT();
    this.zoomfactor = 0.3;
    this.width = width;
    this.height = height;
    this.x = x;
    this.y = y;
    this.round = 5/this.zoomfactor;
    this.steps = 5;
    this.penstroke = 2;
    // ##SKINNY MODE
    // Inactive hides the plot and prevents waveform() reads. LayoutManager
    // also omits this component's panel while the flag is true.
    this.inactive = false;
    // p5.FFT subscribes to p5.soundOut.fftMeter immediately. We keep explicit
    // connection state so Skinny mode can remove this analyzer from the audio
    // graph while the panel is hidden.
    this.analyzerConnected = true;
    }

	//draw the wave form to the screen
	draw(){
        // Skip before calling p5.FFT.waveform(); the analyzer read is the work
        // we want to avoid on constrained devices.
        if (this.inactive) {
            return;
        }
        this.connectAnalyzer();

		push();

        translate(this.x, this.y);
        scale(this.zoomfactor);
        
        //panel background
        fill(UI.surface[0], UI.surface[1], UI.surface[2]);
        rect(0,0,this.width,this.height,this.round);
        stroke(UI.text[0], UI.text[1], UI.text[2], 28);
        strokeWeight(1/this.zoomfactor);
        for (let y = 0; y < this.height; y += 70) {
            line(0, y, this.width, y);
        }
        for (let x = 0; x < this.width; x += 100) {
            line(x, 0, x, this.height);
        }
        noFill();
        const trace = UI.waveformTrace || UI.pink;
        stroke(trace[0], trace[1], trace[2], 150);
        strokeWeight(1/this.zoomfactor);
        rect(0,0,this.width,this.height,this.round);
		
		stroke(trace[0], trace[1], trace[2]);
		strokeWeight(this.penstroke * 1.25);   //width of the line

		beginShape();
		//calculate the waveform from the fft.
		var wave = this.fourier.waveform();
		for (var i = 0; i < wave.length; i+=this.steps){ //Every N samples to save cpu
			//for each element of the waveform map it to screen 
			//coordinates and make a new vertex at the point.
			var x = map(i, 0, wave.length, 0, this.width);
			var y = map(wave[i], -0.8, 0.8, 0, this.height); //plot amplitude from -0.8 to 0.8

			vertex(x, y);
		}

		endShape();
		pop();
	}

    setZoom(val){
        this.zoomfactor = val;
    }

    setSteps(val){
        this.steps = val;
    }

    setStroke(val){
        this.penstroke = val;
    }

    setInactive(value) {
        // ##SKINNY MODE
        // This is the module-level low-power entry point called by sketch.js.
        this.inactive = !!value;
        if (this.inactive) {
            // Skipping draw() avoids waveform() reads; disconnecting also stops
            // p5.sound from feeding this unused analyser node.
            this.disconnectAnalyzer();
        } else {
            // The FFT instance remains alive, so re-enabling is just a reconnect.
            this.connectAnalyzer();
        }
    }

    isInactive() {
        return this.inactive;
    }

    connectAnalyzer() {
        if (this.analyzerConnected || !this.fourier || !this.fourier.analyser) {
            return;
        }

        try {
            if (window.p5 && p5.soundOut && p5.soundOut.fftMeter) {
                p5.soundOut.fftMeter.connect(this.fourier.analyser);
                this.analyzerConnected = true;
            }
        } catch (error) {
            // Keep playback safe if the browser refuses the analyzer reconnect.
            this.analyzerConnected = false;
        }
    }

    disconnectAnalyzer() {
        if (!this.analyzerConnected || !this.fourier || !this.fourier.analyser) {
            return;
        }

        try {
            if (window.p5 && p5.soundOut && p5.soundOut.fftMeter) {
                // Targeted disconnect avoids cutting off other active FFT
                // visualizers that also listen to p5.soundOut.fftMeter.
                p5.soundOut.fftMeter.disconnect(this.fourier.analyser);
            }
        } catch (error) {
            // Older browsers can throw on targeted disconnect. The inactive
            // draw guard still prevents waveform() from doing CPU work.
        }
        this.analyzerConnected = false;
    }

    fitToPanel(panel) {
        const displayW = Math.max(80, panel.w - 40);
        const displayH = Math.max(50, panel.h - 50);
        this.x = panel.x + 20;
        this.y = panel.y + 35;
        this.width = displayW / this.zoomfactor;
        this.height = displayH / this.zoomfactor;
        this.round = 5 / this.zoomfactor;
    }

    getMinPanelSize() {
        return { w: 220, h: 120 };
    }
}

/* ---- lib/spectrum.js ---- */
/**
 * Class representing a spectrum visualizer using p5.js.
 * Draws a real-time frequency spectrum as a bar graph.
 *
 * @class
 * @property {string} name - The name of the visualizer ("spectrum").
 * @property {p5.FFT} fourier - The p5.FFT instance for frequency analysis.
 * @property {number} zoomfactor - The zoom factor for scaling the visualization.
 * @property {number} width - The width of the spectrum visualization.
 * @property {number} height - The height of the spectrum visualization.
 * @property {number} x - The x-coordinate of the visualization's position.
 * @property {number} y - The y-coordinate of the visualization's position.
 * @property {number} round - The border radius for the visualization background.
 * @property {number} steps - The step size for sampling spectrum bins (affects bar width and CPU usage).
 *
 * @constructor
 * @param {number} x - The x-coordinate for the visualization.
 * @param {number} y - The y-coordinate for the visualization.
 * @param {number} width - The width of the visualization.
 * @param {number} height - The height of the visualization.
 *
 * @method draw - Renders the spectrum visualization on the canvas.
 * @method setZoom - Sets the zoom factor for the visualization.
 * @param {number} val - The new zoom factor.
 * @method setSteps - Sets the step size for spectrum bin sampling.
 * @param {number} val - The new step size.
 */
class Spectrum{

    constructor(x,y,width,height){
	this.name = "spectrum";
    this.fourier = new p5.FFT();
    this.zoomfactor = 0.3;
    this.width = width;
    this.height = height;
    this.x = x;
    this.y = y;
    this.round = 5/this.zoomfactor;
    this.steps = 20;
    // ##SKINNY MODE
    // Inactive means this analyzer-backed plot is hidden and should not call
    // p5.FFT.analyze() from draw(). The panel also disappears via LayoutManager.
    this.inactive = false;
    // p5.FFT connects to p5.soundOut.fftMeter in its constructor. Track that
    // connection so Skinny mode can remove the analyzer from the audio graph,
    // not merely skip the canvas drawing work.
    this.analyzerConnected = true;
    this.lastTelemetry = null;

    }

	draw(){
        // Returning before analyze() is the important performance behavior.
        // Drawing less often is not enough on slow devices if FFT still runs.
        if (this.inactive) {
            return;
        }
        this.connectAnalyzer();

		push();

        translate(this.x, this.y)
        scale(this.zoomfactor);
        
        //panel background
        fill(UI.surface[0], UI.surface[1], UI.surface[2]);
        rect(0,0,this.width,this.height,this.round);
        stroke(UI.text[0], UI.text[1], UI.text[2], 28);
        strokeWeight(1/this.zoomfactor);
        for (let y = 0; y < this.height; y += 70) {
            line(0, y, this.width, y);
        }
        
		var spectrum = this.fourier.analyze();
        this.updateTelemetry(spectrum);
        
        //Bars
		noStroke();
        const barCount = Math.ceil(spectrum.length / this.steps);
        const gap = Math.max(2 / this.zoomfactor, this.width * 0.002);
        const barWidth = Math.max(2 / this.zoomfactor, (this.width - gap * (barCount + 1)) / barCount);

		for (var i = 0; i< spectrum.length; i+=this.steps){   //Every N steps to save cpu
            const barIndex = Math.floor(i / this.steps);
            const energy = spectrum[i];
            fill(UI.line[0], UI.line[1], UI.line[2], map(energy, 0, 255, 70, 235));
                   
            var x = gap + barIndex * (barWidth + gap);
		    var h = -map(spectrum[i], 0, 255, 0, this.height);
            rect(x, this.height-2, barWidth, h);

  		}
        
        //border
        stroke(UI.line[0], UI.line[1], UI.line[2], 120);
        strokeWeight(1/this.zoomfactor);
        noFill();
        rect(0,0,this.width,this.height,this.round);

		pop();
	};

    setZoom(val){
        this.zoomfactor = val;
    }

    setSteps(val){
        this.steps = val;
    }

    setInactive(value) {
        // ##SKINNY MODE
        // This is the module-level low-power entry point called by sketch.js.
        this.inactive = !!value;
        if (this.inactive) {
            // Disconnecting the FFT analyzer removes its Web Audio fan-out from
            // the output bus. This is heavier than just hiding the panel, but it
            // is the part that matters on low-power devices.
            this.disconnectAnalyzer();
        } else {
            // Keep the FFT object allocated; reconnecting is enough to resume.
            this.connectAnalyzer();
        }
    }

    isInactive() {
        return this.inactive;
    }

    connectAnalyzer() {
        if (this.analyzerConnected || !this.fourier || !this.fourier.analyser) {
            return;
        }

        try {
            if (window.p5 && p5.soundOut && p5.soundOut.fftMeter) {
                p5.soundOut.fftMeter.connect(this.fourier.analyser);
                this.analyzerConnected = true;
            }
        } catch (error) {
            // If the browser rejects this connection, leave the visualizer safe
            // but silent instead of risking playback.
            this.analyzerConnected = false;
        }
    }

    disconnectAnalyzer() {
        if (!this.analyzerConnected || !this.fourier || !this.fourier.analyser) {
            return;
        }

        try {
            if (window.p5 && p5.soundOut && p5.soundOut.fftMeter) {
                // Disconnect only this FFT analyzer. Calling disconnect()
                // without a target would remove every FFT listener.
                p5.soundOut.fftMeter.disconnect(this.fourier.analyser);
            }
        } catch (error) {
            // Some older Web Audio implementations are picky about targeted
            // disconnects. The draw guard still prevents analyze() calls.
        }
        this.analyzerConnected = false;
    }

    /**
     * Stores a compact summary of the last FFT frame for the DATA FEED sampler.
     * This keeps the visualizer responsible for measurement, not log wording.
     */
    updateTelemetry(spectrum) {
        let peakIndex = 0;
        let peakValue = 0;
        let energy = 0;
        // Find the strongest FFT bin and average energy from the same data
        // already used for drawing, so telemetry does not trigger extra FFT work.
        for (let i = 0; i < spectrum.length; i++) {
            const value = spectrum[i] || 0;
            energy += value;
            if (value > peakValue) {
                peakValue = value;
                peakIndex = i;
            }
        }

        // p5 FFT bins span 0 Hz through Nyquist. Use sampleRate() when p5 has
        // initialized audio, otherwise fall back to the common 44.1 kHz rate.
        const nyquist = typeof sampleRate === "function" ? sampleRate() / 2 : 22050;
        this.lastTelemetry = {
            dominantHz: Math.round((peakIndex / Math.max(1, spectrum.length - 1)) * nyquist),
            peak: Math.round(peakValue),
            energy: Math.round(energy / Math.max(1, spectrum.length))
        };
    }

    /**
     * Returns the latest spectrum summary for central telemetry sampling.
     */
    getTelemetry() {
        return this.lastTelemetry;
    }

    fitToPanel(panel) {
        const displayW = Math.max(80, panel.w - 40);
        const displayH = Math.max(50, panel.h - 50);
        this.x = panel.x + 20;
        this.y = panel.y + 35;
        this.width = displayW / this.zoomfactor;
        this.height = displayH / this.zoomfactor;
        this.round = 5 / this.zoomfactor;
    }

    getMinPanelSize() {
        return { w: 220, h: 120 };
    }


}

/* ---- lib/vumeters.js ---- */
/**
 * Class representing stereo-style VU meters using p5.js and p5.sound data.
 * By default it reads p5.sound's main output, so EQ/reverb/output gain changes
 * are reflected in the meters. Set inputMode: "source" to inspect the raw
 * p5.SoundFile buffer instead.
 */
class VUMeters {

    constructor(x, y, width, height, options = {}) {
        this.name = "vumeters";

        // Canvas-space bounds. The sketch can keep these tied to a panel,
        // the same way Spectrum and WaveForm are panel-bound.
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.zoomfactor = options.zoomfactor || 1;
        this.round = 5 / this.zoomfactor;

        // Output mode measures the final p5.sound mix. Source mode measures
        // the raw p5.SoundFile buffer before this app's EQ/reverb routing.
        this.inputMode = options.inputMode || "output";
        this.source = null;
        this.amplitude = new p5.Amplitude();

        // VU meters are usually read in dB. These values map the measured
        // signal into a normalized 0..1 fill amount for drawing.
        this.minDb = options.minDb || -54;
        this.maxDb = options.maxDb || 0;

        // Attack rises quickly, release falls slower. This avoids twitchy
        // meters while still making hits feel immediate.
        this.attack = options.attack || 0.38;
        this.release = options.release || 0.08;
        this.peakDecay = options.peakDecay || 0.012;

        // Number of recent audio samples used to calculate RMS level.
        this.sampleWindow = options.sampleWindow || 1024;

        this.leftLevel = 0;
        this.rightLevel = 0;
        this.leftPeak = 0;
        this.rightPeak = 0;
        // ##SKINNY MODE
        // Inactive VU meters skip amplitude reads and are hidden by the panel
        // manager. The p5.Amplitude object is kept for fast reactivation.
        this.inactive = false;
        // p5.Amplitude connects an AudioWorklet to p5.soundOut.meter in its
        // constructor. Track that edge so Skinny mode can remove the worklet
        // from the live audio graph instead of only skipping getLevel().
        this.meterConnected = true;
    }

    setInactive(value) {
        // ##SKINNY MODE
        // This is the module-level low-power entry point called by sketch.js.
        this.inactive = !!value;
        if (this.inactive) {
            // Disconnecting the meter input is the expensive-work cutoff. The
            // worklet object stays allocated, but it no longer receives frames.
            this.disconnectMeter();
        } else {
            // Reconnect to the main output meter when the panel becomes visible.
            this.connectMeter();
        }
    }

    isInactive() {
        return this.inactive;
    }

    setSource(source) {
        // Avoid touching analyzer inputs while the panel is hidden.
        if (this.inactive) {
            return;
        }

        this.source = source || null;
        if (this.inputMode === "source" && this.source && this.amplitude && typeof this.amplitude.setInput === "function") {
            try {
                // Source mode fallback follows the same sound object.
                this.amplitude.setInput(this.source);
            } catch (error) {
                // Some p5.sound nodes cannot be used as direct amplitude inputs.
            }
        }
    }

    draw(source = null) {
        // Return before updateLevels(), which is where p5.Amplitude.getLevel()
        // would read from the output bus.
        if (this.inactive) {
            return;
        }
        this.connectMeter();

        if (source && source !== this.source) {
            this.setSource(source);
        }

        this.updateLevels();

        push();
        translate(this.x, this.y);
        scale(this.zoomfactor);

        fill(UI.surface[0], UI.surface[1], UI.surface[2]);
        stroke(UI.line[0], UI.line[1], UI.line[2], 120);
        strokeWeight(1 / this.zoomfactor);
        rect(0, 0, this.width, this.height, this.round);

        this.drawMeter("L", this.leftLevel, this.leftPeak, 18);
        this.drawMeter("R", this.rightLevel, this.rightPeak, this.width / 2 + 8);

        noFill();
        stroke(UI.line[0], UI.line[1], UI.line[2], 120);
        rect(0, 0, this.width, this.height, this.round);

        pop();
    }

    connectMeter() {
        if (this.meterConnected || !this.amplitude || !this.amplitude._workletNode) {
            return;
        }

        try {
            if (window.p5 && p5.soundOut && p5.soundOut.meter) {
                p5.soundOut.meter.connect(this.amplitude._workletNode);
                this.meterConnected = true;
            }
        } catch (error) {
            // Leave the meter disconnected if the browser refuses reconnecting;
            // playback should never depend on the visualizer graph.
            this.meterConnected = false;
        }
    }

    disconnectMeter() {
        if (!this.meterConnected || !this.amplitude || !this.amplitude._workletNode) {
            return;
        }

        try {
            if (window.p5 && p5.soundOut && p5.soundOut.meter) {
                // Target only this VU worklet. A broad disconnect would disable
                // any other p5.Amplitude listeners in the app.
                p5.soundOut.meter.disconnect(this.amplitude._workletNode);
            }
        } catch (error) {
            // Targeted disconnect can throw on older Web Audio builds. The draw
            // guard still keeps getLevel() and RMS smoothing out of the loop.
        }
        this.meterConnected = false;
    }

    /**
     * Rebuilds the p5.Amplitude node used by the VU meter.
     * PERF PATCH [audio-runtime-periodic-maintenance]: Firefox profiles showed
     * long-session CPU accumulating in AudioWorklet processing. This lets the
     * periodic player maintenance replace the VU meter worklet without
     * recreating the visible component or losing its panel geometry.
     */
    recycleAudioNodes() {
        this.disconnectMeter();

        try {
            if (this.amplitude && typeof this.amplitude.dispose === "function") {
                this.amplitude.dispose();
            }
        } catch (error) {
            // The meter is visual-only; failed disposal should not interrupt playback.
        }

        this.amplitude = new p5.Amplitude();
        this.meterConnected = true;
        // PERF PATCH [audio-runtime-periodic-maintenance]: drop the previous
        // SoundFile reference; the next draw() call will attach the new source.
        this.source = null;
        this.leftLevel = 0;
        this.rightLevel = 0;
        this.leftPeak = 0;
        this.rightPeak = 0;

        if (this.inactive) {
            // Preserve Skinny mode after replacing the p5.Amplitude worklet.
            this.disconnectMeter();
        }
    }

    updateLevels() {
        const levels = this.readStereoLevels();

        // Smooth the raw measurement before drawing, then maintain a separate
        // peak marker that decays slowly from recent maxima.
        this.leftLevel = this.smoothLevel(this.leftLevel, levels.left);
        this.rightLevel = this.smoothLevel(this.rightLevel, levels.right);
        this.leftPeak = Math.max(this.leftPeak - this.peakDecay, this.leftLevel);
        this.rightPeak = Math.max(this.rightPeak - this.peakDecay, this.rightLevel);
    }

    readStereoLevels() {
        if (this.inputMode === "source") {
            // Source mode tries the actual decoded L/R samples first.
            const sampled = this.readSoundFileLevels();
            if (sampled) {
                return sampled;
            }
        }

        // Output mode: p5.Amplitude listens to the main output by default.
        // getLevel(0/1) gives the post-FX left/right meter values.
        let left = 0;
        let right = 0;
        try {
            left = this.amplitude ? this.amplitude.getLevel(0) : 0;
            right = this.amplitude ? this.amplitude.getLevel(1) : left;
        } catch (error) {
            left = 0;
            right = 0;
        }
        left = Number.isFinite(left) ? left : 0;
        right = Number.isFinite(right) ? right : left;

        return {
            left: this.levelToNormalized(left),
            right: this.levelToNormalized(right)
        };
    }

    readSoundFileLevels() {
        if (!this.source || !this.source.buffer || typeof this.source.currentTime !== "function") {
            return null;
        }

        // p5.SoundFile stores its decoded AudioBuffer at source.buffer.
        // Reading a short window before currentTime gives a live-ish RMS level.
        const buffer = this.source.buffer;
        if (!buffer || !buffer.numberOfChannels || !buffer.sampleRate || typeof buffer.getChannelData !== "function") {
            return null;
        }

        const currentSample = Math.floor(this.source.currentTime() * buffer.sampleRate);
        const start = Math.max(0, currentSample - this.sampleWindow);
        const end = Math.min(buffer.length || 0, currentSample);
        if (end <= start) {
            return null;
        }

        const left = this.rmsFromChannel(buffer.getChannelData(0), start, end);
        const right = buffer.numberOfChannels > 1
            ? this.rmsFromChannel(buffer.getChannelData(1), start, end)
            : left;

        return {
            left: this.levelToNormalized(left),
            right: this.levelToNormalized(right)
        };
    }

    rmsFromChannel(channelData, start, end) {
        // Root mean square is a good visual loudness estimate for the meter.
        let sum = 0;
        for (let i = start; i < end; i++) {
            const sample = channelData[i] || 0;
            sum += sample * sample;
        }

        return Math.sqrt(sum / Math.max(1, end - start));
    }

    levelToNormalized(level) {
        // Convert linear amplitude to dB, then map into the meter range.
        const db = 20 * Math.log10(Math.max(0.000001, level));
        return constrain(map(db, this.minDb, this.maxDb, 0, 1), 0, 1);
    }

    smoothLevel(previous, next) {
        // Separate attack/release makes rises snappy and falls weighted.
        const amount = next > previous ? this.attack : this.release;
        return previous + (next - previous) * amount;
    }

    drawMeter(label, level, peak, x) {
        const meterW = Math.max(18, this.width / 2 - 28);
        const meterH = Math.max(60, this.height - 42);
        const y = 18;
        const peakY = y + meterH - meterH * peak;

        noStroke();
        fill(UI.field[0], UI.field[1], UI.field[2]);
        rect(x, y, meterW, meterH, 4);

        const segmentCount = 18;
        const segmentGap = 2;
        const segmentH = (meterH - segmentGap * (segmentCount - 1)) / segmentCount;
        for (let i = 0; i < segmentCount; i++) {
            // Segments are drawn bottom-up. Higher segments change color to
            // amber/pink so hot levels are legible at a glance.
            const segmentLevel = (i + 1) / segmentCount;
            const segmentY = y + meterH - (i + 1) * segmentH - i * segmentGap;
            const active = segmentLevel <= level;
            const colorValue = this.segmentColor(segmentLevel);
            fill(colorValue[0], colorValue[1], colorValue[2], active ? 220 : 36);
            rect(x + 4, segmentY, meterW - 8, segmentH, 2);
        }

        stroke(UI.text[0], UI.text[1], UI.text[2], 220);
        strokeWeight(2 / this.zoomfactor);
        line(x + 3, peakY, x + meterW - 3, peakY);

        noFill();
        stroke(UI.line[0], UI.line[1], UI.line[2], 120);
        strokeWeight(1 / this.zoomfactor);
        rect(x, y, meterW, meterH, 4);

        noStroke();
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(10);
        textAlign(CENTER, CENTER);
        text(label, x + meterW / 2, this.height - 12);
    }

    segmentColor(level) {
        // Use the current theme palette so the component works in CYBER/STELLAR.
        if (level > 0.86) {
            return UI.pink;
        }
        if (level > 0.68) {
            return UI.amber;
        }
        return UI.line;
    }

    setZoom(val) {
        this.zoomfactor = val;
        this.round = 5 / this.zoomfactor;
    }

    setSize(width, height) {
        this.width = width;
        this.height = height;
    }

    fitToPanel(panel) {
        this.x = panel.x + 16;
        this.y = panel.y + 34;
        this.setSize(Math.max(70, panel.w - 32), Math.max(80, panel.h - 48));
    }

    getMinPanelSize() {
        return { w: 110, h: 135 };
    }

    /**
     * Returns the smoothed meter state for the central telemetry sampler.
     * Values are normalized 0..1, matching the levels used by drawMeter().
     */
    getTelemetry() {
        return {
            left: this.leftLevel,
            right: this.rightLevel,
            leftPeak: this.leftPeak,
            rightPeak: this.rightPeak
        };
    }
}

/* ---- lib/vectorscope.js ---- */
/**
 * Stereo vectorscope for the final p5.sound output bus.
 *
 * The scope taps p5.soundOut.input with a ChannelSplitter and two analysers.
 * It does not reroute or consume audio; Web Audio nodes can fan out to this
 * visualizer while the normal output path keeps playing.
 */
class VectorScope {
    constructor(x, y, width, height, options = {}) {
        this.name = "vectorscope";
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.zoomfactor = options.zoomfactor || 1;
        this.round = 5 / this.zoomfactor;

        this.fftSize = options.fftSize || 1024;
        this.sampleStep = options.sampleStep || 3;
        this.connected = false;
        this.correlation = 0;

        this.context = null;
        this.splitter = null;
        this.leftAnalyser = null;
        this.rightAnalyser = null;
        this.leftBuffer = new Float32Array(this.fftSize);
        this.rightBuffer = new Float32Array(this.fftSize);
        // ##SKINNY MODE
        // Inactive means hidden and disconnected from p5.soundOut.input. This
        // avoids the analyser fan-out work while Skinny mode is enabled.
        this.inactive = false;

        this.connectToOutput();
    }

    connectToOutput() {
        // Do not reconnect while inactive. Skinny mode controls this state
        // through setInactive().
        if (this.inactive) {
            return;
        }

        if (this.connected || !window.p5 || !p5.soundOut || !p5.soundOut.input || !p5.soundOut.audiocontext) {
            return;
        }

        try {
            this.context = p5.soundOut.audiocontext;
            this.splitter = this.context.createChannelSplitter(2);
            this.leftAnalyser = this.createAnalyser();
            this.rightAnalyser = this.createAnalyser();

            p5.soundOut.input.connect(this.splitter);
            this.splitter.connect(this.leftAnalyser, 0);
            this.splitter.connect(this.rightAnalyser, 1);
            this.connected = true;
        } catch (error) {
            console.warn("VectorScope could not connect to p5.soundOut:", error);
            this.connected = false;
        }
    }

    disconnectFromOutput() {
        // Disconnect analyzer-only nodes. They are not part of the audible path,
        // so this should never interrupt playback.
        try {
            if (this.splitter) {
                this.splitter.disconnect();
            }
            if (this.leftAnalyser) {
                this.leftAnalyser.disconnect();
            }
            if (this.rightAnalyser) {
                this.rightAnalyser.disconnect();
            }
        } catch (error) {
            // Web Audio nodes can throw when already disconnected.
        }

        this.splitter = null;
        this.leftAnalyser = null;
        this.rightAnalyser = null;
        this.connected = false;
    }

    setInactive(value) {
        // ##SKINNY MODE
        // This is the module-level low-power entry point called by sketch.js.
        this.inactive = !!value;
        if (this.inactive) {
            // VectorScope owns real Web Audio analyzer nodes, so it can do more
            // than skip draw(): it can remove its tap from the output bus.
            this.disconnectFromOutput();
        } else {
            this.connectToOutput();
        }
    }

    isInactive() {
        return this.inactive;
    }

    createAnalyser() {
        const analyser = this.context.createAnalyser();
        analyser.fftSize = this.fftSize;
        analyser.smoothingTimeConstant = 0.45;
        return analyser;
    }

    draw() {
        // Skip before reading analyzer buffers and calculating correlation.
        if (this.inactive) {
            return;
        }

        this.connectToOutput();
        this.readSamples();

        push();
        translate(this.x, this.y);
        scale(this.zoomfactor);

        this.drawFrame();
        this.drawTrace();
        this.drawCorrelation();

        pop();
    }

    readSamples() {
        if (!this.connected || !this.leftAnalyser || !this.rightAnalyser) {
            this.leftBuffer.fill(0);
            this.rightBuffer.fill(0);
            this.correlation = 0;
            return;
        }

        this.leftAnalyser.getFloatTimeDomainData(this.leftBuffer);
        this.rightAnalyser.getFloatTimeDomainData(this.rightBuffer);
        this.correlation = this.calculateCorrelation();
    }

    calculateCorrelation() {
        let lr = 0;
        let ll = 0;
        let rr = 0;

        for (let i = 0; i < this.leftBuffer.length; i += this.sampleStep) {
            const left = this.leftBuffer[i] || 0;
            const right = this.rightBuffer[i] || 0;
            lr += left * right;
            ll += left * left;
            rr += right * right;
        }

        const denominator = Math.sqrt(ll * rr);
        if (!denominator) {
            return 0;
        }

        return constrain(lr / denominator, -1, 1);
    }

    drawFrame() {
        fill(UI.surface[0], UI.surface[1], UI.surface[2]);
        stroke(UI.line[0], UI.line[1], UI.line[2], 120);
        strokeWeight(1 / this.zoomfactor);
        rect(0, 0, this.width, this.height, this.round);

        const centerX = this.width / 2;
        const scopeTop = 12;
        const scopeSize = this.getScopeSize();
        const centerY = scopeTop + scopeSize / 2;

        stroke(UI.text[0], UI.text[1], UI.text[2], 28);
        line(centerX - scopeSize / 2, centerY, centerX + scopeSize / 2, centerY);
        line(centerX, centerY - scopeSize / 2, centerX, centerY + scopeSize / 2);
        line(centerX - scopeSize / 2, centerY + scopeSize / 2, centerX + scopeSize / 2, centerY - scopeSize / 2);
        line(centerX - scopeSize / 2, centerY - scopeSize / 2, centerX + scopeSize / 2, centerY + scopeSize / 2);

        noFill();
        stroke(UI.line[0], UI.line[1], UI.line[2], 85);
        ellipse(centerX, centerY, scopeSize, scopeSize);
    }

    drawTrace() {
        const centerX = this.width / 2;
        const scopeTop = 12;
        const scopeSize = this.getScopeSize();
        const centerY = scopeTop + scopeSize / 2;
        const radius = scopeSize * 0.48;
        const trace = UI.waveformTrace || UI.line;

        noFill();
        stroke(trace[0], trace[1], trace[2], 185);
        strokeWeight(1.4 / this.zoomfactor);
        beginShape();

        for (let i = 0; i < this.leftBuffer.length; i += this.sampleStep) {
            const left = constrain(this.leftBuffer[i] || 0, -1, 1);
            const right = constrain(this.rightBuffer[i] || 0, -1, 1);

            // Classic Lissajous mapping: horizontal shows stereo difference,
            // vertical shows summed mono energy.
            const side = (right - left) * 0.5;
            const mid = (right + left) * 0.5;
            vertex(centerX + side * radius * 2, centerY - mid * radius * 2);
        }

        endShape();
    }

    drawCorrelation() {
        const barW = Math.max(60, this.width - 34);
        const barH = 8;
        const x = (this.width - barW) / 2;
        const y = this.height - 24;
        const markerX = x + map(this.correlation, -1, 1, 0, barW);

        noStroke();
        fill(UI.field[0], UI.field[1], UI.field[2]);
        rect(x, y, barW, barH, 4);

        fill(UI.line[0], UI.line[1], UI.line[2], 210);
        rect(x, y, markerX - x, barH, 4);

        stroke(UI.text[0], UI.text[1], UI.text[2], 220);
        strokeWeight(2 / this.zoomfactor);
        line(markerX, y - 3, markerX, y + barH + 3);

        noStroke();
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(9);
        textAlign(CENTER, CENTER);
        text(`CORR ${this.correlation.toFixed(2)}`, this.width / 2, this.height - 9);
    }

    getScopeSize() {
        return Math.max(54, Math.min(this.width - 24, this.height - 48));
    }

    setSize(width, height) {
        this.width = width;
        this.height = height;
    }

    fitToPanel(panel) {
        this.x = panel.x + 16;
        this.y = panel.y + 34;
        this.setSize(Math.max(90, panel.w - 32), Math.max(80, panel.h - 48));
    }

    getMinPanelSize() {
        return { w: 130, h: 130 };
    }

    /**
     * Returns the latest stereo correlation summary for the DATA FEED sampler.
     */
    getTelemetry() {
        return {
            correlation: this.correlation,
            field: this.describeStereoField()
        };
    }

    /**
     * Converts numeric correlation into a short readable field state.
     */
    describeStereoField() {
        // Negative correlation can indicate phase cancellation risk.
        if (this.correlation < -0.2) {
            return "phase warning";
        }
        // Low positive correlation means the signal is wide but not inverted.
        if (this.correlation < 0.25) {
            return "wide";
        }
        // Very high correlation is close to mono/centered content.
        if (this.correlation > 0.82) {
            return "mono";
        }
        return "stable";
    }
}

/* ---- lib/playinginfo.js ---- */
/**
 * PlayingInfo class
 * This class is used to display the current song information
 * including title, album, artist, and cover art.
 *
 */
class PlayingInfo{


    constructor(x,y,subsonicObj){
        this.x=x;
        this.y=y;
        this.title = "";
        this.album = "";
        this.artist = "";
        this.cover = "";
        // PERF PATCH [bounded-cover-cache]: keep recent cover images for
        // repeated albums without retaining artwork for an entire session.
        this.coverCache = new Map();
        this.maxCoverCacheEntries = 24;
        this.isBusy=false;
        this.subsonicObj = subsonicObj;
    }

    setSong(currentSong){

        try{

            this.title = currentSong.title || "";
            this.album = currentSong.album || "";
            this.artist = currentSong.artist || "";
            this.coverid = currentSong.coverArt;
            //Load cover art
            if(this.coverid){
                if (this.coverCache.has(this.coverid)) {
                    this.cover = this.coverCache.get(this.coverid);
                    return;
                }

                const requestedCoverId = this.coverid;
                const img = this.subsonicObj.getCoverArt(this.coverid);
                this.cover = loadImage(img,
                                        ()=>{                                       //success callback
                                            if (this.coverid === requestedCoverId) {
                                                this.cacheCover(requestedCoverId, this.cover);
                                            }
                                        },
                                        ()=>{                                       //error callback
                                            if (this.coverid !== requestedCoverId) {
                                                return;
                                            }
                                            this.createFallbackCover();
                                        });
            }else{
                this.createFallbackCover();
            }


        }catch{

        }
    }

    /**
     * Stores a loaded cover image in a small insertion-ordered cache.
     * Repeated albums can reuse images while older artwork is released.
     * @param {string} coverId - Subsonic cover art identifier.
     * @param {p5.Image} image - Loaded cover image to cache.
     */
    cacheCover(coverId, image) {
        // PERF PATCH [bounded-cover-cache]: Map insertion order gives a tiny
        // LRU-style cache without retaining every cover loaded for hours.
        if (!coverId || !image) {
            return;
        }

        if (this.coverCache.has(coverId)) {
            this.coverCache.delete(coverId);
        }
        this.coverCache.set(coverId, image);

        while (this.coverCache.size > this.maxCoverCacheEntries) {
            const oldestKey = this.coverCache.keys().next().value;
            this.coverCache.delete(oldestKey);
        }
    }

    createFallbackCover(){
        //Create false cover to cover (oj, oj)
        this.cover = createImage(100,100);
        this.cover.loadPixels();
        for (let i = 0; i < this.cover.width; i++) {
            for (let j = 0; j < this.cover.height; j++) {
                this.cover.set(i, j, color(0, 90, 102, (i % this.cover.width) * 2));
            }
        }
        this.cover.updatePixels();
    }


    draw(){
        push();

        fill(UI.surface[0], UI.surface[1], UI.surface[2], 235);
        stroke(UI.line[0], UI.line[1], UI.line[2], 140);
        strokeWeight(1);

        rect(this.x,this.y,350,120,6);//cover border
        noStroke();
        fill(UI.line[0], UI.line[1], UI.line[2], 24);
        rect(this.x + 1, this.y + 1, 348, 22, 5);

        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(15);
        textStyle(BOLD);
        text(this.title || "No track selected", this.x+124, this.y+34, 210);
        textStyle(NORMAL);
        fill(UI.muted[0], UI.muted[1], UI.muted[2]);
        textSize(12);
        text(this.album || "Album pending", this.x+124, this.y+62, 210);
        fill(UI.line[0], UI.line[1], UI.line[2]);
        text(this.artist || "Artist pending", this.x+124, this.y+84, 210);

        try{
            image(this.cover,this.x+10,this.y+10);
            noFill();

        }catch{

        }
            noFill();
            stroke(UI.line[0], UI.line[1], UI.line[2], 150);
            rect(this.x+9,this.y+9,101,101,4);

        if(this.isBusy){
            fill(UI.pink);  //Busy downloading indicator
        }else{
            fill(UI.bg);    //Not busy indicator
        }
            noStroke();
            ellipse(this.x+340, this.y+110,10,10);//Busy indicator

        pop();

       this.isBusy=false;
    }

    drawBusy(){
        this.isBusy=true;
    }

    getLayoutBounds(){
        return { x: this.x, y: this.y, w: 350, h: 120 };
    }

    moveTo(x, y){
        this.x = x;
        this.y = y;
    }

}

/* ---- lib/player.js ---- */
class Player {
    /**
     * Creates a new Player instance.
     * @param {SubsonicClient} subsonicClient - The Subsonic API client for fetching songs.
     * @param {PlayList} playlist - The playlist object to manage songs.
     */
    constructor(subsonicClient, playlist) {
        this.subsonicClient = subsonicClient; // Subsonic API client
        this.playlist = playlist; // Playlist object
        this.song = null; // p5.SoundFile object for playback
        this.keepPlaying = false; // Semaphore for continuous playback
        this.loopPlaylist = true; // Whether to loop the playlist
        this.isLoading = false; // Flag to prevent multiple loads
        this.isRequested = false; // Flag to indicate if the song is freshly loaded. The idea is to avoid the sketch from reassigning the sound object every frame. Set to true when the song is requested from the sketch.
        this.onSongLoaded = null; // Optional callback for UI metadata updates.
        this.onMaintenance = null; // Optional callback for periodic audio-runtime maintenance.
        // PERF PATCH [bounded-load-progress-log]: keep loading logs sparse so
        // long sessions with DevTools open do not retain thousands of rows.
        this.lastLoadProgressPercent = -1;
        // PERF PATCH [firefox-graphrunner-idle-suspend]: remember the pending
        // suspend timer so pause/play bursts do not race GraphRunner cleanup.
        this.audioIdleSuspendTimer = null;
        // PERF PATCH [audio-runtime-periodic-maintenance]: long Firefox
        // sessions can accumulate WebAudio/AudioWorklet CPU inside p5.sound.
        // Count completed tracks and insert a small maintenance gap so the app
        // can detach/recycle runtime nodes before loading the next stream.
        this.completedPlaybackCount = 0;
        this.maintenanceInterval = 50;
        this.maintenanceDelayMs = 1000;
        this.isPerformingMaintenance = false;

        //Loads dummy sound to init the sound system
        this.song=loadSound('assets/dot.mp3', () => console.log("Player: Dummy sound loaded."));
    }

    setOnSongLoaded(callback) {
        this.onSongLoaded = callback;
    }

    /**
     * Registers a callback for periodic audio-runtime maintenance.
     * PERF PATCH [audio-runtime-periodic-maintenance]: sketch.js uses this
     * hook to log the maintenance cycle and recycle visualization/FX nodes
     * outside Player, keeping Player focused on transport state.
     * @param {function|null} callback - Receives maintenance event details.
     */
    setOnMaintenance(callback) {
        this.onMaintenance = callback;
    }

    /**
     * Plays a song from the file path.
     * @param {string} filepath - The file path of the song to play.
     * @param {function} [onEndCallback] - Optional callback to execute when the song ends.
     */
    playSongFromFile(filepath) {
        if (this.isLoading) {
            console.warn("Player: A song is already loading. Please wait.");
            return;
        }

        const previousSong = this.detachCurrentSong();
        // PERF PATCH [soundfile-handoff-release]: dispose the old decoded
        // buffer before the next load to avoid a two-track decode peak.
        this.disposeSound(previousSong);
        this.resetLoadProgressLog();

        this.isLoading = true; // Set loading flag
        this.song = loadSound(
            filepath,
            () => {
                console.log(`Player: Loaded song from ${filepath}`);
                this.isLoading = false; // Clear loading flag
                this.playSong();

            },
            () => {
                console.error(`Player: Failed to load song from ${filepath}`);
                this.isLoading = false; // Clear loading flag on error
                this.disposeSound(this.song);
                this.song = null;
            },
            (progress) => {
                this.logLoadProgress(progress);
            }
        );
    }

    /**
     * Plays a song from its index in the playlist.
     * @param {string} index - The position on the playlist to play.
     */
    playSongByPlaylistId(index) {
        if (index === undefined || index === null) {
            console.warn("Player: Playlist index is undefined or null.");
            return;
        }

        var id=null;
        try {
            id = this.playlist.getSong(index).id;
        } catch (error) {
            console.warn(`Player: Invalid playlist index ${index}`);
            return;
        }


        if (!id) {
            console.warn(`Player: Song ID ${id} not found in playlist`);
            return;
        }
        
        this.playlist.setPointer(index);//just in case it was called elsewhere
        this.playSongById(id);

    }

    /**
     * Plays a song from its ID in the playlist.
     * @param {string} id - The ID of the song to play.
     * @param {function} [onEndCallback] - Optional callback to execute when the song ends.
     */
    playSongById(id) {
        if (this.isLoading) {
            console.warn("Player: A song is already loading. Please wait.");
            return;
        }

        //just crosscheck if the song is in the playlist
        const position = this.playlist.getPointerFromSongId(id);
        if (position !== -1) {
            this.playlist.setPointer(position);
            const songUrl = this.subsonicClient.getSong(id);

            const previousSong = this.detachCurrentSong();
            // PERF PATCH [soundfile-handoff-release]: release the previous
            // p5.SoundFile before fetching and decoding the next stream.
            this.disposeSound(previousSong);
            this.resetLoadProgressLog();

            this.isLoading = true; // Set loading flag
            this.song = loadSound(
                songUrl,
                () => {
                    console.log(`Player: Loaded song with ID ${id}`);
                    this.isLoading = false; // Clear loading flag
                    this.playSong();
                    this.notifySongLoaded(id);
                    
                },
                () => {
                    console.error(`Player: Failed to load song with ID ${id}`);
                    this.isLoading = false; // Clear loading flag on error
                    this.disposeSound(this.song);
                    this.song = null;
                },
                (progress) => {
                    this.logLoadProgress(progress);
                }
            );
        } else {
            console.warn(`Player: Song ID ${id} not found in playlist`);
        }
    }

    notifySongLoaded(id) {
        if (!this.onSongLoaded) {
            return;
        }

        try {
            this.onSongLoaded(id, this.playlist.getCurrent());
        } catch (error) {
            console.error("Player: onSongLoaded callback failed:", error);
        }
    }

    /**
     * Emits the maintenance callback without letting UI/log failures break
     * playback handoff.
     * PERF PATCH [audio-runtime-periodic-maintenance]: maintenance is a
     * defensive runtime patch, so telemetry must be best-effort only.
     * @param {Object} event - Maintenance details for logging/diagnostics.
     */
    notifyMaintenance(event) {
        if (!this.onMaintenance) {
            return;
        }

        try {
            this.onMaintenance(event);
        } catch (error) {
            console.error("Player: onMaintenance callback failed:", error);
        }
    }

    detachCurrentSong() {
        // A song change can otherwise leave decoded buffers and Web Audio nodes
        // alive after several tracks. Stop immediately and let callers dispose
        // the detached object before loading the next decoded buffer.
        const previousSong = this.song;
        if (previousSong) {
            try {
                previousSong.stop();
            } catch (error) {
                // Some p5.SoundFile instances can throw if they are mid-load.
            }
        }
        this.song = null;
        this.isRequested = false;
        return previousSong;
    }

    disposeSound(soundFile) {
        // PERF PATCH [soundfile-handoff-release]: p5.SoundFile.dispose()
        // removes the object from p5.sound's soundArray and disconnects graph
        // nodes, but Firefox can retain decoded buffers unless we also clear
        // p5.SoundFile's internal references below.
        if (!soundFile) {
            return;
        }

        try {
            if (typeof soundFile.dispose === "function") {
                soundFile.dispose();
            }
        } catch (error) {
            console.warn("Player: Could not dispose previous sound file:", error);
        }

        this.releaseSoundFileReferences(soundFile);
    }

    /**
     * Returns p5.sound's shared AudioContext when it is available.
     * PERF PATCH [firefox-graphrunner-idle-suspend]: all GraphRunner
     * suspend/resume work must use the same context that p5.sound owns.
     *
     * Developer note: getAudioContext() is provided by p5.sound in this app.
     * Access is guarded because tests/static checks can load this file without
     * a browser AudioContext.
     * @returns {AudioContext|null} The active p5.sound AudioContext.
     */
    getManagedAudioContext() {
        if (typeof getAudioContext === "function") {
            try {
                return getAudioContext();
            } catch (error) {
                return null;
            }
        }

        return null;
    }

    /**
     * Cancels a queued idle suspend before starting or resuming playback.
     * PERF PATCH [firefox-graphrunner-idle-suspend]: quick pause/play
     * interactions must not suspend AudioContext after playback has resumed.
     */
    cancelAudioIdleSuspend() {
        if (!this.audioIdleSuspendTimer) {
            return;
        }

        clearTimeout(this.audioIdleSuspendTimer);
        this.audioIdleSuspendTimer = null;
    }

    /**
     * Resumes p5.sound's AudioContext before playback starts.
     * PERF PATCH [firefox-graphrunner-idle-suspend]: pause/stop can suspend
     * Firefox's WebAudio graph to make GraphRunner sleep, so playback requests
     * must wake the same context before calling p5.SoundFile.play().
     *
     * Developer note: resume() returns a Promise in modern browsers. Playback
     * is still attempted immediately by callers because p5.sound also handles
     * user-gesture resume paths; the Promise is used for diagnostics only.
     */
    resumeAudioContextForPlayback() {
        this.cancelAudioIdleSuspend();

        const audioContext = this.getManagedAudioContext();
        if (!audioContext || audioContext.state !== "suspended" || typeof audioContext.resume !== "function") {
            return;
        }

        try {
            const resumeResult = audioContext.resume();
            if (resumeResult && typeof resumeResult.catch === "function") {
                resumeResult.catch((error) => {
                    console.warn("Player: Could not resume AudioContext for playback:", error);
                });
            }
        } catch (error) {
            console.warn("Player: Could not resume AudioContext for playback:", error);
        }
    }

    /**
     * Suspends p5.sound's AudioContext specifically for maintenance gaps.
     * PERF PATCH [audio-runtime-periodic-maintenance]: this intentionally
     * bypasses the idle guards used by suspendAudioContextWhenIdle() because
     * the player is between tracks and wants a short GraphRunner sleep before
     * the next SoundFile rebuilds the graph.
     */
    suspendAudioContextForMaintenance() {
        const audioContext = this.getManagedAudioContext();
        if (!audioContext || audioContext.state !== "running" || typeof audioContext.suspend !== "function") {
            return;
        }

        try {
            const suspendResult = audioContext.suspend();
            if (suspendResult && typeof suspendResult.catch === "function") {
                suspendResult.catch((error) => {
                    console.warn("Player: Could not suspend AudioContext for maintenance:", error);
                });
            }
        } catch (error) {
            console.warn("Player: Could not suspend AudioContext for maintenance:", error);
        }
    }

    /**
     * Schedules p5.sound's AudioContext suspension while playback is idle.
     * PERF PATCH [firefox-graphrunner-idle-suspend]: Firefox keeps
     * GraphRunner active while the WebAudio graph is running, even when a
     * p5.SoundFile is paused or stopped. Suspending AudioContext sleeps it.
     *
     * Developer note: the small delay avoids suspend/resume churn if the user
     * taps Pause and Play immediately, and it avoids interfering with active
     * track handoff where the next song should start without a GraphRunner
     * restart.
     * @param {number} delayMs - Delay before suspending the AudioContext.
     */
    suspendAudioContextWhenIdle(delayMs = 1200) {
        this.cancelAudioIdleSuspend();

        this.audioIdleSuspendTimer = setTimeout(() => {
            this.audioIdleSuspendTimer = null;
            if (this.isLoading || this.keepPlaying || (this.song && this.song.isPlaying && this.song.isPlaying())) {
                return;
            }

            const audioContext = this.getManagedAudioContext();
            if (!audioContext || audioContext.state !== "running" || typeof audioContext.suspend !== "function") {
                return;
            }

            try {
                const suspendResult = audioContext.suspend();
                if (suspendResult && typeof suspendResult.catch === "function") {
                    suspendResult.catch((error) => {
                        console.warn("Player: Could not suspend idle AudioContext:", error);
                    });
                }
            } catch (error) {
                console.warn("Player: Could not suspend idle AudioContext:", error);
            }
        }, delayMs);
    }

    /**
     * Clears p5.SoundFile fields that dispose() leaves reachable in Firefox.
     * PERF PATCH [soundfile-internal-reference-release]: decoded AudioBuffer
     * objects are large native allocations, so old tracks must drop buffer and
     * source references as soon as the player advances to the next song.
     *
     * Developer note: this intentionally reaches into p5.sound internals.
     * In long Firefox sessions, p5.SoundFile.dispose() disconnects the audible
     * graph but can leave decoded buffers, source nodes, and the position
     * tracking AudioWorklet reachable long enough to grow RAM or keep
     * GraphRunner busy. These fields belong to a discarded SoundFile and must
     * not be reused after handoff, so clearing them is safer than waiting for
     * p5.sound/browser cleanup heuristics.
     * @param {p5.SoundFile} soundFile - Discarded p5.SoundFile instance.
     */
    releaseSoundFileReferences(soundFile) {
        try {
            // PERF PATCH [soundfile-internal-reference-release]: source nodes
            // can retain their AudioBuffer after dispose() disconnects output.
            if (Array.isArray(soundFile.bufferSourceNodes)) {
                for (const node of soundFile.bufferSourceNodes) {
                    this.releaseAudioBufferSource(node, soundFile);
                }
                soundFile.bufferSourceNodes.length = 0;
            }

            this.releaseAudioBufferSource(soundFile.bufferSourceNode, soundFile);
            soundFile.bufferSourceNode = null;
            this.releaseAudioBufferSource(soundFile._counterNode, soundFile);
            soundFile._counterNode = null;
            // PERF PATCH [soundfile-worklet-release]: p5.sound creates
            // _workletNode as a silent position tracker for each SoundFile.
            // Discarded connected trackers can keep GraphRunner processing.
            this.releaseAudioWorkletNode(soundFile._workletNode);
            soundFile._workletNode = null;

            // PERF PATCH [soundfile-internal-reference-release]: dispose()
            // disconnects graph nodes but does not clear decoded AudioBuffer.
            // Keeping it matches the observed RAM growth while skipping songs.
            soundFile.buffer = null;
            // PERF PATCH [soundfile-internal-reference-release]: callbacks,
            // cues, and files can keep discarded SoundFiles reachable.
            soundFile._onended = function () {};
            soundFile._whileLoading = function () {};
            soundFile._cues = [];
            soundFile.file = null;
            soundFile.url = null;
        } catch (error) {
            console.warn("Player: Could not release sound file references:", error);
        }
    }

    /**
     * Disconnects/stops an AudioBufferSourceNode and severs its buffer link.
     * PERF PATCH [soundfile-internal-reference-release]: cleanup for
     * discarded p5.SoundFile source nodes.
     *
     * Developer note: p5.sound stores every started source in
     * bufferSourceNodes until its ended handler trims the array. Rapid track
     * handoff can leave old source nodes waiting for that cleanup while they
     * still reference the decoded AudioBuffer. We remove the handler, stop the
     * node, disconnect it, and clear node.buffer when the browser permits it.
     * @param {AudioBufferSourceNode|null} node - Web Audio source node.
     * @param {p5.SoundFile} soundFile - Owner used to remove p5 ended handler.
     */
    releaseAudioBufferSource(node, soundFile) {
        if (!node) {
            return;
        }

        try {
            if (soundFile && soundFile._clearOnEnd && typeof node.removeEventListener === "function") {
                // PERF PATCH [soundfile-internal-reference-release]: remove
                // p5.sound's ended handler so old SoundFiles can be released.
                node.removeEventListener("ended", soundFile._clearOnEnd);
            }
        } catch (error) {
            // Some source nodes may already have been finalized by p5.sound.
        }

        try {
            node.disconnect();
        } catch (error) {
            // Already-disconnected AudioBufferSourceNodes throw in some browsers.
        }

        try {
            node.stop();
        } catch (error) {
            // stop() throws after a source has already stopped; safe to ignore.
        }

        try {
            // PERF PATCH [soundfile-internal-reference-release]: sever the
            // native AudioBuffer reference when the browser allows it.
            node.buffer = null;
        } catch (error) {
            // Some implementations expose buffer as non-writable after start.
        }
    }

    /**
     * Disconnects the p5.SoundFile position-tracking AudioWorklet.
     * PERF PATCH [soundfile-worklet-release]: p5.sound connects this worklet
     * to a silent timing output, and orphaned worklets can keep Firefox's
     * GraphRunner busy even after playback is paused.
     *
     * Developer note: GraphRunner is the Firefox WebAudio graph execution
     * thread seen in about:processes/profiler. A disconnected visual player can
     * still burn CPU there if stale AudioWorkletNodes remain connected to the
     * silent output path. Closing the MessagePort and disconnecting the node
     * ensures the discarded SoundFile no longer schedules work.
     * @param {AudioWorkletNode|null} node - Internal p5.sound worklet node.
     */
    releaseAudioWorkletNode(node) {
        if (!node) {
            return;
        }

        try {
            if (node.port) {
                // PERF PATCH [soundfile-worklet-release]: remove the message
                // callback so the discarded SoundFile cannot stay reachable.
                node.port.onmessage = null;
                if (typeof node.port.close === "function") {
                    node.port.close();
                }
            }
        } catch (error) {
            // Some AudioWorklet ports may already be closed by the browser.
        }

        try {
            node.disconnect();
        } catch (error) {
            // Already-disconnected AudioWorkletNodes can throw.
        }
    }

    /**
     * Resets sparse load-progress logging for the next track request.
     */
    resetLoadProgressLog() {
        this.lastLoadProgressPercent = -1;
    }

    /**
     * Logs coarse loading progress buckets instead of every p5.sound progress
     * callback, keeping long-session console memory bounded.
     * @param {number} progress - Fractional loading progress from p5.sound.
     */
    logLoadProgress(progress) {
        // PERF PATCH [bounded-load-progress-log]: p5.sound can emit many
        // progress callbacks per track. Buckets keep console history bounded.
        const percent = Math.round((Number(progress) || 0) * 100);
        const bucket = Math.floor(percent / 25) * 25;
        if (bucket <= this.lastLoadProgressPercent && percent < 100) {
            return;
        }

        this.lastLoadProgressPercent = Math.max(bucket, percent);
        console.log(`Player: Loading song... ${percent}%`);
    }


    /**
     * Plays the currently loaded song.
     */
    playSong() {
        if (this.song && this.song.isPlaying()) {
            console.log("Player: Song is already playing");
            return;
        }

        if (this.song && this.song.isLoaded()) {
            this.resumeAudioContextForPlayback();
            this.isRequested = false; // Indicate that the song has not been requested from the sketch yet
            this.song.play();
            this.keepPlaying = true;
            console.log("Player: Playing song");
        } else {
            console.warn("Player: No song loaded to play");
        }
    }

    /**
     * Pauses the currently playing song.
     */
    pauseSong() {
        if (this.song && this.song.isPlaying()) {
            this.song.pause();
            this.keepPlaying = false;
            this.suspendAudioContextWhenIdle();
            console.log("Player: Paused song");
        }
    }

    /**
     * Stops the currently playing song.
     */
    stopSong() {
        if (this.song) {
            this.song.stop();
            this.keepPlaying = false;
            this.suspendAudioContextWhenIdle();
            console.log("Player: Stopped song");
        }
    }

    /**
     * Plays the next song in the playlist.
     */
    playNext() {
        if (this.isLoading) {
            console.warn("Player: A song is already loading. Skipping playNext.");
            return;
        }
        if (this.playlist.getLength() === 0) {
            console.warn("Player: No songs in the playlist");
            return;
        }

        const advanced = this.playlist.next(this.loopPlaylist);// advance the pointer
        if (advanced) {
            this.playSongByPlaylistId(this.playlist.getPointer());
        } else {
            this.stopSong();
            console.warn("Player: No next song in the playlist");
        }

    }

    /**
     * Handles natural end-of-track advancement and periodic maintenance.
     * PERF PATCH [audio-runtime-periodic-maintenance]: the counter is based on
     * completed playbacks rather than queue index so random/loop playback still
     * refreshes the audio runtime every N actual songs.
     */
    handleSongEnded() {
        this.completedPlaybackCount++;

        if (this.shouldPerformMaintenance()) {
            this.performMaintenance(() => this.playNext());
            return;
        }

        this.playNext();
    }

    /**
     * Reports whether the next track handoff should include maintenance.
     * PERF PATCH [audio-runtime-periodic-maintenance]: default cadence is 50
     * completed songs, matching the observed overnight Firefox CPU drift.
     * @returns {boolean} True when maintenance should run before advancing.
     */
    shouldPerformMaintenance() {
        return this.maintenanceInterval > 0 &&
            this.completedPlaybackCount > 0 &&
            this.completedPlaybackCount % this.maintenanceInterval === 0;
    }

    /**
     * Inserts a short maintenance gap between completed songs.
     * PERF PATCH [audio-runtime-periodic-maintenance]: this detaches the ended
     * SoundFile, clears p5.sound internals, asks sketch.js to recycle app-owned
     * audio nodes, and briefly suspends AudioContext so Firefox GraphRunner can
     * drop stale work before the next stream starts.
     * @param {function} continuePlayback - Called after the maintenance gap.
     */
    performMaintenance(continuePlayback) {
        if (this.isPerformingMaintenance) {
            return;
        }

        const completedCount = this.completedPlaybackCount;
        this.isPerformingMaintenance = true;
        this.isLoading = true;
        const shouldContinue = this.keepPlaying;

        const previousSong = this.detachCurrentSong();
        this.disposeSound(previousSong);
        this.resetLoadProgressLog();
        this.keepPlaying = false;

        const event = {
            completedCount: completedCount,
            interval: this.maintenanceInterval,
            delayMs: this.maintenanceDelayMs
        };
        this.notifyMaintenance(event);
        this.suspendAudioContextForMaintenance();

        setTimeout(() => {
            this.isPerformingMaintenance = false;
            this.isLoading = false;
            this.keepPlaying = shouldContinue;

            if (shouldContinue && typeof continuePlayback === "function") {
                continuePlayback();
            }
        }, this.maintenanceDelayMs);
    }

    /**
     * Plays the previous song in the playlist.
     */
    playPrevious() {
        if (this.isLoading) {
            console.warn("Player: A song is already loading. Skipping playPrevious.");
            return;
        }
        if (this.playlist.getLength() === 0) {
            console.warn("Player: No songs in the playlist");
            return;
        }

        const advanced = this.playlist.previous(true);
        if (advanced) {
            this.playSongByPlaylistId(this.playlist.getPointer());
        } else {
            console.warn("Player: No previous song in the playlist");
        }
    }

    /**
     * Toggles looping for the playlist.
     */
    setLoop(loop) {
        //this.loopPlaylist = !this.loopPlaylist;
        this.loopPlaylist = loop;
        //console.log(`Player: Looping is now ${this.loopPlaylist ? "enabled" : "disabled"}`);
    }

    /**
     * Starts playing the full playlist in a loop.
     */
    playFullPlaylist() {
        this.keepPlaying = true;
        const currentSong = this.playlist.getCurrent();
        if (currentSong) {
            this.playSongById(currentSong.id);
        } else {
            console.warn("Player: Playlist is empty");
        }
    }

    getProgress(){
        if(this.song && this.song.isLoaded()){
            return this.song.currentTime() / this.song.duration();
        }
        return 0;  
    }

    /**
     * Exposes the current p5.SoundFile object for external use (e.g., applying filters).
     * @returns {p5.SoundFile|null} The current sound object, or null if no song is loaded.
     * Note: This method returns the sound object only once after loading or playing a new song to avoid reassigning it every frame.
     */
    getSoundObject() {
        if(!this.isRequested){
            this.isRequested = true; // Reset the flag after the first request
            return this.song;
        }
        return null ;//to avoid reassigning the sound object every frame. See in sketch.js draw()
    }


    draw() {
        //Not actual drawing code, just controlling the NEXT song if keepPlaying is true
        //This is actually a dirty way because the onended() is not reliable
        if (this.keepPlaying && !this.isLoading && !this.isPerformingMaintenance && this.getProgress() >= 0.999) { //detect song ended
            this.handleSongEnded();
        }   
    }


}

/* ---- lib/switch.js ---- */
class Switch {
    constructor(x, y, w = 30, h = 60, label) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.isOn = false;
        this.label = label;
    }

    draw() {
        push();
        stroke(this.isOn ? color(UI.line[0], UI.line[1], UI.line[2]) : color(UI.muted[0], UI.muted[1], UI.muted[2]));
        fill(this.isOn ? color(UI.line[0], UI.line[1], UI.line[2], 54) : color(UI.field[0], UI.field[1], UI.field[2]));
        rect(this.x, this.y, this.w, this.h, this.w / 2);

        let handleY = this.isOn ? this.w/2 : this.w/2+this.h - this.w;
        fill(UI.text[0], UI.text[1], UI.text[2]);
        stroke(this.isOn ? color(UI.line[0], UI.line[1], UI.line[2]) : color(UI.muted[0], UI.muted[1], UI.muted[2]));
        ellipse(this.x+this.w/2, this.y+handleY, this.w * 0.8);

        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(10);
        textAlign(CENTER, CENTER);
        noStroke();
        text(this.label, this.x + this.w / 2, this.y + this.h+15);

        pop();
    }

    handleMouse(mx, my) {
        if (
            mx > this.x && mx < this.x + this.w &&
            my > this.y && my < this.y + this.h
        ) {
            this.isOn = !this.isOn;
        }
    }

    // Query methods
    getState() {
        return this.isOn;
    }

    isEnabled() {
        return this.isOn;
    }

    isDisabled() {
        return !this.isOn;
    }

    setState(val) {
        this.isOn = !!val;
    }

    getLayoutBounds() {
        return { x: this.x, y: this.y, w: this.w, h: this.h + 20 };
    }

    moveTo(x, y) {
        this.x = x;
        this.y = y;
    }
}

/* ---- lib/slider_v.js ---- */
/**
 * Vertical Slider Component
 * 
 * This class defines a vertical slider UI component that can be used in p5.js sketches.
 * The slider allows users to select a value within a specified range by dragging a handle along a vertical track.
 * The track color interpolates between two specified colors based on the current value.
 * 
 * Usage:
 * const slider = new SliderV(x, y, width, height, label, min, max, defaultValue, color1, color2);
 */
class SliderV {
    // Constructor
    /**
     * 
     * @param {number} x - The x-coordinate of the slider's top-left corner.
     * @param {number} y - The y-coordinate of the slider's top-left corner.
     * @param {number} w - The width of the slider.
     * @param {number} h - The height of the slider.
     * @param {string} label - The label for the slider.
     * @param {number} min - The minimum value of the slider.
     * @param {number} max - The maximum value of the slider.
     * @param {number} defaultValue - The default value of the slider.
     * @param {string} color1 - The color representing the minimum value.
     * @param {string} color2 - The color representing the maximum value.
     * @param {object} [opts] - Optional settings: { wheelSteps, wheelSensitivity }.
     */
    constructor(x, y, w = 30, h = 120, label, min = 0, max = 100, defaultValue = 50, color1, color2, opts = {}) {
        this.x = x; 
        this.y = y;
        this.w = w;
        this.h = h;
        this.label = label;
        this.color1 = color1 || '#cccccc';
        this.color2 = color2 || '#00ff00';

        this.min = min;
        this.max = max;
        this.value = defaultValue;

        this.isDragging = false;

        // Wheel behaviour configuration
        // wheelSteps: how many fractional steps the wheel moves across the full range (higher -> smaller increments)
        // wheelSensitivity: multiplier to tune speed of wheel reaction
        this.wheelSteps = opts.wheelSteps || 100;
        this.wheelSensitivity = opts.wheelSensitivity || 1;
    }

    draw() {
        push();

        // Define colors for min and max values
        const minColor = color(this.color1);//color('#ccc'); // Default gray
        const maxColor = color(this.color2);//color(0,255,0); //color("#5d9e5fff"); // A pleasant green

        // Calculate the interpolation amount (0 to 1)
        const t = map(this.value, this.min, this.max, 0, 1);

        // Interpolate the color for the track
        const trackColor = lerpColor(minColor, maxColor, t);

        // Draw track
        noStroke();
        fill(UI.surface[0], UI.surface[1], UI.surface[2], 210);
        rect(this.x - 5, this.y - 5, this.w + 10, this.h + 10, 6);
        stroke(UI.line[0], UI.line[1], UI.line[2], 90);
        fill(UI.field[0], UI.field[1], UI.field[2]);
        rect(this.x, this.y, this.w, this.h, this.w / 2);

        noStroke();
        fill(trackColor);
        const activeHeight = map(this.value, this.min, this.max, 0, this.h);
        rect(this.x, this.y + this.h - activeHeight, this.w, activeHeight, this.w / 2);

        // Calculate handle position
        const handleRadius = this.w / 2;
        const handleY = map(this.value, this.min, this.max, this.y + this.h - handleRadius, this.y + handleRadius);

        // Draw handle
        fill(UI.text[0], UI.text[1], UI.text[2]);
        stroke(UI.line[0], UI.line[1], UI.line[2]);
        strokeWeight(1);
        //elongated rectangle for handle
        rectMode(RADIUS);
        rect(this.x+this.w/2, handleY, this.w*0.7, Math.max(4, this.w/3-4), this.w / 5);
        
        //circle for handle
        //ellipse(this.x + this.w / 2, handleY, this.w * 0.8);

        //three vertical lines inside the handle to indicate grip
        //stroke(0);
        //strokeWeight(1);
        //line(this.x + this.w / 2 - 5, handleY - 2, this.x + this.w / 2 - 5, handleY + 2);
        //line(this.x + this.w / 2, handleY - 2, this.x + this.w / 2, handleY + 2);
        //line(this.x + this.w / 2 + 5, handleY - 2, this.x + this.w / 2 + 5, handleY + 2);


        // Reset rect mode
        rectMode(CORNER);

        // Draw label
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(10);
        textAlign(CENTER, CENTER);
        noStroke();
        text(this.label, this.x + this.w / 2, this.y + this.h + 15);

        pop();
    }

    // This should be called from the p5.js mousePressed() function
    handleMouse(mx, my) {
        // Click anywhere on the track to jump there, then drag from that point.
        if (this.isMouseOver(mx, my)) {
            this.isDragging = true;
            this._updateValueFromMouse(my); // Snap to precise mouse Y on click for responsiveness
        }
    }

    // This should be called from the p5.js mouseDragged() function
    mouseDragged(mx, my) {
        if (this.isDragging) {
            this._updateValueFromMouse(my);
        }
    }

    // This should be called from the p5.js mouseReleased() function
    mouseReleased() {
        this.isDragging = false;
    }

    _updateValueFromMouse(my) {
        const handleRadius = this.w / 2;
        const constrainedY = constrain(my, this.y + handleRadius, this.y + this.h - handleRadius);
        this.value = map(constrainedY, this.y + this.h - handleRadius, this.y + handleRadius, this.min, this.max);
    }

    /**
     * Handle mouse wheel events to change slider value.
     * Call this from your sketch's global mouseWheel(event) handler:
     *   function mouseWheel(event) { mySlider.handleWheel(event); }
     *
     * The slider only reacts when the pointer is over the slider bounds.
     * @param {WheelEvent|Object} event - The wheel event passed by p5 (has delta or deltaY).
     */
    handleWheel(event) {
        // Use current global mouseX/mouseY from p5 to detect hovering
        if (!this.isMouseOver(mouseX, mouseY)) return;

        const deltaY = (event.deltaY !== undefined) ? event.deltaY : (event.delta || 0);

        // Normalize delta to a sensible change amount:
        // positive deltaY usually means scrolling down (want to decrease slider),
        // negative means scrolling up (increase slider).
        const range = this.max - this.min;
        const unit = range / this.wheelSteps; // base unit per wheel "step"
        const change = - (deltaY / 100) * unit * this.wheelSensitivity; // scale deltaY

        this.setValue(this.value + change);

        // Prefer to prevent page scroll when interacting with slider
        if (event.preventDefault) event.preventDefault();
        return false;
    }

    /**
     * Returns true if given coordinate (or current mouse) is over slider area.
     * @param {number} [mx=mouseX] - x coordinate to test.
     * @param {number} [my=mouseY] - y coordinate to test.
     */
    isMouseOver(mx = mouseX, my = mouseY) {
        return mx >= this.x && mx <= (this.x + this.w) && my >= this.y && my <= (this.y + this.h);
    }

    // Query/Set methods
    getValue() {
        return this.value;
    }

    setValue(val) {
        this.value = constrain(val, this.min, this.max);
    }

    getLayoutBounds() {
        return { x: this.x - 5, y: this.y - 5, w: this.w + 10, h: this.h + 30 };
    }

    moveTo(x, y) {
        this.x = x + 5;
        this.y = y + 5;
    }
}

/* ---- lib/slider_h.js ---- */
/**
 * Horizontal Slider Component
 * 
 * Class representing a horizontal slider UI component.
 * This slider allows users to select a value within a specified range by dragging a handle along a horizontal track.
 * The track color interpolates between two specified colors based on the current value.
 * 
 * Usage:
 * const slider = new SliderH(x, y, width, height, label, min, max, defaultValue, color1, color2, opts);
 * Call slider.handleWheel(event) from your sketch's global mouseWheel handler when needed.
 */
class SliderH {
    /**
     * Creates a new SliderH instance.
     * @param {number} x - The x-coordinate of the slider.
     * @param {number} y - The y-coordinate of the slider.
     * @param {number} w - The width of the slider.
     * @param {number} h - The height of the slider.
     * @param {string} label - The label for the slider.
     * @param {number} min - The minimum value of the slider.
     * @param {number} max - The maximum value of the slider.
     * @param {number} defaultValue - The default value of the slider.
     * @param {string} color1 - Color for minimum value.
     * @param {string} color2 - Color for maximum value.
     * @param {object} [opts] - Optional settings: { wheelSteps, wheelSensitivity }.
     */
    constructor(x, y, w = 120, h = 30, label, min = 0, max = 100, defaultValue = 50, color1 = '#cccccc', color2 = '#5d9e5fff', opts = {}) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.label = label;
        this.color1 = color1;
        this.color2 = color2;

        this.min = min;
        this.max = max;
        this.value = defaultValue;

        this.isDragging = false;

        // Wheel behaviour configuration
        // wheelSteps: how many fractional steps the wheel moves across the full range (higher -> smaller increments)
        // wheelSensitivity: multiplier to tune speed of wheel reaction
        this.wheelSteps = opts.wheelSteps || 100;
        this.wheelSensitivity = opts.wheelSensitivity || 1;
    }

    /**
     * Draws the slider on the canvas.
     */
    draw() {
        push();

        // Define colors for min and max values
        const minColor = color(this.color1);
        const maxColor = color(this.color2);

        // Calculate the interpolation amount (0 to 1)
        const t = map(this.value, this.min, this.max, 0, 1);

        // Interpolate the color for the track
        const trackColor = lerpColor(minColor, maxColor, t);

        // Draw track
        noStroke();
        fill(UI.surface[0], UI.surface[1], UI.surface[2], 210);
        rect(this.x - 4, this.y - 4, this.w + 8, this.h + 8, 6);
        stroke(UI.line[0], UI.line[1], UI.line[2], 90);
        fill(UI.field[0], UI.field[1], UI.field[2]);
        rect(this.x, this.y, this.w, this.h, this.h / 2);

        noStroke();
        fill(trackColor);
        const activeWidth = map(this.value, this.min, this.max, 0, this.w);
        rect(this.x, this.y, activeWidth, this.h, this.h / 2);

        // Calculate handle position
        const handleRadius = this.h / 2;
        const handleX = map(this.value, this.min, this.max, this.x + handleRadius, this.x + this.w - handleRadius);

        // Draw handle
        fill(UI.text[0], UI.text[1], UI.text[2]);
        stroke(UI.line[0], UI.line[1], UI.line[2]);
        strokeWeight(1);
        ellipse(handleX, this.y + this.h / 2, this.h * 1.6);

        // Draw label
        fill(UI.text[0], UI.text[1], UI.text[2]);
        textSize(10);
        textAlign(CENTER, CENTER);
        noStroke();
        text(this.label, this.x + this.w / 2, this.y + this.h + 15);

        pop();
    }

    /**
     * Handles mouse pressed events.
     * @param {number} mx - The x-coordinate of the mouse.
     * @param {number} my - The y-coordinate of the mouse.
     */
    handleMouse(mx, my) {
        // Click anywhere on the track to jump there, then drag from that point.
        if (this.isMouseOver(mx, my)) {
            this.isDragging = true;
            this._updateValueFromMouse(mx); // Snap to precise mouse X on click for responsiveness
        }
    }

    /**
     * Handles mouse dragged events.
     * @param {number} mx - The x-coordinate of the mouse.
     * @param {number} my - The y-coordinate of the mouse.
     */
    mouseDragged(mx, my) {
        if (this.isDragging) {
            this._updateValueFromMouse(mx);
        }
    }

    /**
     * Handles mouse released events.
     */
    mouseReleased() {
        this.isDragging = false;
    }

    /**
     * Updates the slider value based on the mouse position.
     * @param {number} mx - The x-coordinate of the mouse.
     */
    _updateValueFromMouse(mx) {
        const handleRadius = this.h / 2;
        const constrainedX = constrain(mx, this.x + handleRadius, this.x + this.w - handleRadius);
        this.value = map(constrainedX, this.x + handleRadius, this.x + this.w - handleRadius, this.min, this.max);
    }

    /**
     * Handle mouse wheel events to change slider value.
     * Call this from your sketch's global mouseWheel(event) handler:
     *   function mouseWheel(event) { mySlider.handleWheel(event); }
     *
     * The slider only reacts when the pointer is over the slider bounds.
     * @param {WheelEvent|Object} event - The wheel event passed by p5 (has delta or deltaY).
     */
    handleWheel(event) {
        // Use current global mouseX/mouseY from p5 to detect hovering
        if (!this.isMouseOver(mouseX, mouseY)) return;

        // Prefer horizontal delta if available, otherwise use vertical delta (typical mouse wheel)
        const rawDelta = (event.deltaX !== undefined && Math.abs(event.deltaX) > 0) ? event.deltaX
                         : (event.deltaY !== undefined ? event.deltaY
                         : (event.delta || 0));

        // Normalize delta to a sensible change amount:
        // positive rawDelta usually means scrolling right/down (we invert to match intuitive direction)
        const range = this.max - this.min;
        const unit = range / this.wheelSteps; // base unit per wheel "step"
        const change = - (rawDelta / 100) * unit * this.wheelSensitivity; // scale delta

        this.setValue(this.value + change);

        // Prefer to prevent page scroll when interacting with slider
        if (event.preventDefault) event.preventDefault();
        return false;
    }

    /**
     * Returns true if given coordinate (or current mouse) is over slider area.
     * @param {number} [mx=mouseX] - x coordinate to test.
     * @param {number} [my=mouseY] - y coordinate to test.
     */
    isMouseOver(mx = mouseX, my = mouseY) {
        return mx >= this.x && mx <= (this.x + this.w) && my >= this.y && my <= (this.y + this.h);
    }

    /**
     * Gets the current value of the slider.
     * @returns {number} The current value.
     */
    getValue() {
        return this.value;
    }

    /**
     * Sets the value of the slider.
     * @param {number} val - The new value.
     */
    setValue(val) {
        this.value = constrain(val, this.min, this.max);
    }

    getLayoutBounds() {
        return { x: this.x - 5, y: this.y - 5, w: this.w + 10, h: this.h + 30 };
    }

    moveTo(x, y) {
        this.x = x + 5;
        this.y = y + 5;
    }
}
